const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:33,240", "arabic": "أَلَا تَجْلِسُ يَا رَجُلُ وَتَدَعَنَا نُفَكِّرُ بِهُدُوءٍ؟", "segs": null, "full_uz": "O'tirmaysanmi, odam bola, bizga xotirjam o'ylashga imkon bermaysanmi?", "note": null},
  {"num": 3, "time": "00:00:33,240 --> 00:00:44,219", "arabic": "اِجْلِسْ وَبِهُدُوءٍ. لَا تَقْلَقِي. غَدًا سَنَجْلِسُ مَعًا نُحْصِي ذَرَّاتِ تُرَابِ أَرْضِ بَغْدَادَ بَعْدَ أَنْ بَاعَ أَحْمَدُ دُكَّانَهُ. لَا تَقْلَقِي.", "segs": [{"ar": "اِجْلِسْ وَبِهُدُوءٍ. لَا تَقْلَقِي.", "uz": "o'tir, xotirjam bo'l. Xavotir olma."}, {"ar": "غَدًا سَنَجْلِسُ مَعًا نُحْصِي ذَرَّاتِ تُرَابِ أَرْضِ بَغْدَادَ", "uz": "ertaga birga o'tirib, Bag'dod yerining tuproq zarralarini sanaymiz"}, {"ar": "بَعْدَ أَنْ بَاعَ أَحْمَدُ دُكَّانَهُ. لَا تَقْلَقِي.", "uz": "Ahmad do'konini sotgandan keyin. Xavotir olma."}], "full_uz": "O'tir, xotirjam bo'l. Xavotir olma. Ertaga birga o'tirib, Ahmad do'konini sotgandan keyin Bag'dod yerining tuproq zarralarini sanaymiz. Xavotir olma.", "note": "«ذَرَّاتِ تُرَابِ أَرْضِ بَغْدَادَ نُحْصِي» — kesatiq ma'nosidagi ibora, juda batafsil hisob-kitob qilishni bildiradi."},
  {"num": 4, "time": "00:00:44,219 --> 00:00:49,780", "arabic": "كَفَاكِ عَوِيلًا كَالنِّسَاءِ. اِجْلِسْ أَيُّهَا الْأَحْمَقُ وَدَعْنِي أُفَكِّرْ لَكَ فِي حَلٍّ.", "segs": [{"ar": "كَفَاكِ عَوِيلًا كَالنِّسَاءِ", "uz": "ayollardek yig'lab-siqtashni bas qil"}, {"ar": "اِجْلِسْ أَيُّهَا الْأَحْمَقُ وَدَعْنِي أُفَكِّرْ لَكَ فِي حَلٍّ", "uz": "o'tir, ey ahmoq, va menga sen uchun yechim o'ylab topishga imkon ber"}], "full_uz": "Ayollardek yig'lab-siqtashni bas qil. O'tir, ey ahmoq, va menga sen uchun yechim o'ylab topishga imkon ber.", "note": null},
  {"num": 5, "time": "00:00:49,780 --> 00:00:53,000", "arabic": "حَلٌّ؟ عَنْ أَيِّ حَلٍّ تَتَحَدَّثِينَ يَا أُمِّي؟", "segs": null, "full_uz": "Yechimmi? Qanaqa yechim haqida gapiryapsiz, onajon?", "note": null},
  {"num": 6, "time": "00:00:53,000 --> 00:00:58,579", "arabic": "كُلَّمَا بَحَثْتِ لِي عَنْ حَلٍّ يَا أُمِّي جَاءَتْنِي الْمَصَائِبُ تَتْرَى", "segs": null, "full_uz": "Har safar menga yechim izlaganingizda, onajon, boshimga baxtsizliklar ketma-ket keladi.", "note": null},
  {"num": 7, "time": "00:00:58,579 --> 00:01:00,679", "arabic": "هَذَا جَزَاءُ مَنْ أَطَاعَ النِّسَاءَ", "segs": null, "full_uz": "Ayollarga itoat qilganning jazosi shu.", "note": null},
  {"num": 8, "time": "00:01:00,679 --> 00:01:03,179", "arabic": "اَلرَّجُلُ يَا أُمِّي لَا يُرِيدُ بَيْعَ دُكَّانِهِ", "segs": null, "full_uz": "U kishi, onajon, do'konini sotishni xohlamaydi.", "note": null},
  {"num": 9, "time": "00:01:03,179 --> 00:01:04,840", "arabic": "مَا لِي وَدُكَّانِهِ", "segs": null, "full_uz": "Uning do'koniga nima ishim bor?", "note": null},
  {"num": 10, "time": "00:01:04,840 --> 00:01:09,859", "arabic": "أَوَلَمْ يَكْفِ أَنَّهُ لَمْ يَطْلُبْ مِنَّا أُجْرَةَ الدُّكَّانِ مُنْذُ أَشْهُرٍ؟", "segs": null, "full_uz": "U necha oydan beri do'kon ijarasini so'ramagani yetarli emasmi?", "note": null},
  {"num": 11, "time": "00:01:09,859 --> 00:01:11,260", "arabic": "رَأْفَةً بِحَالِنَا", "segs": null, "full_uz": "Bizning holimizga rahm qilib.", "note": null},
  {"num": 12, "time": "00:01:11,260 --> 00:01:13,960", "arabic": "أَوَهَذَا جَزَاؤُهُ مِنَّا يَا أُمِّي؟", "segs": null, "full_uz": "Bizdan bunga shu javobni beramizmi, onajon?", "note": null},
  {"num": 13, "time": "00:01:13,960 --> 00:01:15,620", "arabic": "ذَلِكَ كُلُّهُ بِسَبَبِكَ", "segs": null, "full_uz": "Bularning barchasi sening sababingdan.", "note": null},
  {"num": 14, "time": "00:01:15,620 --> 00:01:19,420", "arabic": "لِمَ لَمْ تَدْفَعْ إِلَى الرَّجُلِ أُجْرَتَهُ إِلَى الْآنِ؟", "segs": null, "full_uz": "Nega hozirgacha u kishiga ijarasini to'lamading?", "note": null},
  {"num": 15, "time": "00:01:19,420 --> 00:01:21,400", "arabic": "وَأَنْتَ تَمْلِكُ كُلَّ هَذِهِ النُّقُودِ", "segs": null, "full_uz": "Holbuki, senda shuncha pul bor.", "note": null},
  {"num": 16, "time": "00:01:21,400 --> 00:01:24,680", "arabic": "مَاذَا؟ مَاذَا تَقُولِينَ يَا سَلَمَةُ؟", "segs": null, "full_uz": "Nima? Nima deyapsan, Salama?", "note": null},
  {"num": 17, "time": "00:01:24,680 --> 00:01:26,719", "arabic": "اَلْآنَ أَصْبَحْتُ أَنَا الْمُخْطِئَ؟", "segs": null, "full_uz": "Endi men aybdor bo'lib qoldimmi?", "note": null},
  {"num": 18, "time": "00:01:26,719 --> 00:01:30,960", "arabic": "مَنْ كَانَ يَرْسُمُ وَيُخَطِّطُ وَيَكِيدُ لِأَحْمَدَ وَدُكَّانِهِ؟", "segs": null, "full_uz": "Ahmad va uning do'koniga qarshi reja tuzib, fitna uygan kim edi?", "note": null},
  {"num": 19, "time": "00:01:30,960 --> 00:01:33,540", "arabic": "أَمْ تُرَاكُمْ قَدْ نَسِيتُمْ؟", "segs": null, "full_uz": "Yoki unutib qo'ydinglarmi?", "note": null},
  {"num": 20, "time": "00:01:33,540 --> 00:01:37,500", "arabic": "كُفَّ عَنْ هَذَا الْجَدَلِ الْعَقِيمِ وَدَعْنَا نَجْلِسْ لِنُفَكِّرَ بِهُدُوءٍ", "segs": null, "full_uz": "Bu befoyda tortishuvni bas qil, xotirjam o'ylashimiz uchun o'tiraylik.", "note": null},
  {"num": 21, "time": "00:01:37,500 --> 00:01:40,280", "arabic": "لَمْ يَعُدْ يُجْدِي التَّفْكِيرُ نَفْعًا يَا أُمِّي", "segs": null, "full_uz": "Endi o'ylashning foydasi yo'q, onajon.", "note": null},
  {"num": 22, "time": "00:01:40,280 --> 00:01:44,400", "arabic": "وَعَلَيْنَا جَمِيعًا أَنْ نَتَحَمَّلَ جَزَاءَ خُبْثِنَا وَمَكْرِنَا", "segs": null, "full_uz": "Va hammamiz o'z yovuzligimiz va makrimizning jazosini tortishimiz kerak.", "note": null},
  {"num": 23, "time": "00:01:51,400 --> 00:02:13,159", "arabic": "مَا زِلْتَ غَاضِبًا؟", "segs": null, "full_uz": "Hali ham g'azablanyapsanmi?", "note": null},
  {"num": 24, "time": "00:02:13,159 --> 00:02:15,180", "arabic": "كُنْتُ كَذَلِكَ", "segs": null, "full_uz": "Shunday edim.", "note": null},
  {"num": 25, "time": "00:02:15,180 --> 00:02:18,439", "arabic": "أَتَغْضَبُ عَلَى أُمِّكَ؟", "segs": null, "full_uz": "Onangdan xafa bo'lasanmi?", "note": null},
  {"num": 26, "time": "00:02:18,439 --> 00:02:20,000", "arabic": "مَعَاذَ اللَّهِ يَا أُمَّ أَحْمَدَ", "segs": null, "full_uz": "Alloh saqlasin, Umm Ahmad.", "note": null},
  {"num": 27, "time": "00:02:20,000 --> 00:02:24,080", "arabic": "إِنَّمَا أَثَارَ حَفِيظَتِي إِلْحَاحُ عَامِرٍ وَأَهْلِهِ", "segs": null, "full_uz": "Meni g'azablantirgani — Omir va uning yaqinlarining qat'iy talab qilishi edi.", "note": null},
  {"num": 28, "time": "00:02:24,080 --> 00:02:27,300", "arabic": "عَلَى أَمْرٍ يَرَوْنَ فِيهِ نَفْعَهُمْ وَنَرَى فِيهِ غَبْنَنَا", "segs": null, "full_uz": "O'zlari uchun foyda, biz uchun esa zarar deb bilgan bir ish haqida.", "note": null},
  {"num": 29, "time": "00:02:27,300 --> 00:02:34,520", "arabic": "رُبَّمَا رَأَيْتُ أَنَّ بَيْعَ الدُّكَّانِ أَنْفَعُ لَنَا مِنْ كِرَائِهِ", "segs": null, "full_uz": "Balki men do'konni sotish, uni ijaraga berishdan ko'ra foydaliroq, deb o'yladim.", "note": null},
  {"num": 30, "time": "00:02:34,520 --> 00:02:38,180", "arabic": "وَلَكِنْ مَا دُمْتَ عَلَى غَيْرِ قَنَاعَةٍ", "segs": null, "full_uz": "Lekin sen bunga ishonmar ekansan.", "note": null},
  {"num": 31, "time": "00:02:38,180 --> 00:02:41,000", "arabic": "فَالْأَمْرُ زِمَامُهُ بَيْنَ يَدَيْكَ", "segs": null, "full_uz": "Ishning jilovi sening qo'lingda.", "note": null},
  {"num": 32, "time": "00:02:41,000 --> 00:02:44,020", "arabic": "وَالدُّكَّانُ دُكَّانُكَ وَدُكَّانُ أَبِيكَ", "segs": null, "full_uz": "Do'kon esa — sening va otangning do'koni.", "note": null},
  {"num": 33, "time": "00:02:44,020 --> 00:02:46,539", "arabic": "جَزَاكِ اللَّهُ خَيْرًا يَا أُمِّي", "segs": null, "full_uz": "Alloh senga yaxshilik ato etsin, onajon.", "note": null},
  {"num": 34, "time": "00:02:46,539 --> 00:02:48,560", "arabic": "أَنَا وَمَا أَمْلِكُ طَوْعُ أَمْرِكِ", "segs": null, "full_uz": "Men va mulkim — sening amringga bo'ysunuvchimiz.", "note": null},
  {"num": 35, "time": "00:02:48,560 --> 00:02:52,379", "arabic": "اِفْعَلْ مَا تَرَاهُ مُنَاسِبًا يَا وَلَدِي", "segs": null, "full_uz": "Munosib deb bilgan narsangni qil, o'g'lim.", "note": null},
  {"num": 36, "time": "00:03:15,020 --> 00:03:15,980", "arabic": "عَمَّتِي", "segs": null, "full_uz": "Ammajon.", "note": null},
  {"num": 37, "time": "00:03:15,980 --> 00:03:18,539", "arabic": "مَا بِكِ؟", "segs": null, "full_uz": "Senga nima bo'ldi?", "note": null},
  {"num": 38, "time": "00:03:18,539 --> 00:03:23,739", "arabic": "أَثَمَّ مَا تُخْفِينَهُ عَنِّي؟", "segs": null, "full_uz": "Mendan yashirayotgan narsang bormi?", "note": null},
  {"num": 39, "time": "00:03:23,739 --> 00:03:27,639", "arabic": "وَمَا الَّذِي أُخْفِيهِ عَنْكِ يَا ابْنَتِي؟", "segs": null, "full_uz": "Sendan nimani yashiraman, qizim?", "note": null},
  {"num": 40, "time": "00:03:27,639 --> 00:03:29,340", "arabic": "أَسْتَحْلِفُكِ بِاللَّهِ يَا عَمَّتِي", "segs": null, "full_uz": "Alloh haqi so'rayman sizdan, ammajon.", "note": null},
  {"num": 41, "time": "00:03:29,340 --> 00:03:32,180", "arabic": "مُحَمَّدٌ بِخَيْرٍ؟", "segs": null, "full_uz": "Muhammad sog'-salomatmi?", "note": null},
  {"num": 42, "time": "00:03:32,180 --> 00:03:34,439", "arabic": "مَا دَامَ رَبُّهُ يَرْعَاهُ", "segs": null, "full_uz": "Robbisi uni asrab turar ekan.", "note": null},
  {"num": 43, "time": "00:03:34,439 --> 00:03:36,979", "arabic": "فَهُوَ بِخَيْرٍ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, u sog'-salomat.", "note": null},
  {"num": 44, "time": "00:03:36,979 --> 00:03:39,439", "arabic": "لَا تَقْلَقِي يَا ابْنَتِي", "segs": null, "full_uz": "Xavotir olma, qizim.", "note": null},
  {"num": 45, "time": "00:03:39,439 --> 00:03:41,259", "arabic": "لَا تَقْلَقِي بِشَأْنِهِ", "segs": null, "full_uz": "Uning haqida xavotir olma.", "note": null},
  {"num": 46, "time": "00:03:41,259 --> 00:03:44,799", "arabic": "كَيْفَ لَا أَقْلَقُ عَلَيْهِ وَأَنَا أَرَاكِ مَشْغُولَةً عَلَيْهِ", "segs": null, "full_uz": "Sizni ham u haqida tashvishlanayotganingizni ko'rib turib, qanday xavotir olmayin?", "note": null},
  {"num": 47, "time": "00:03:44,799 --> 00:03:47,180", "arabic": "وَأَرَاكِ تَكْتُمِينَ قَلَقَكِ", "segs": null, "full_uz": "Va tashvishingizni yashirayotganingizni ko'ryapman.", "note": null},
  {"num": 48, "time": "00:03:47,180 --> 00:03:51,140", "arabic": "عَمَّتِي أَثَمَّ مَا يَجِبُ أَنْ أَعْرِفَهُ", "segs": null, "full_uz": "Ammajon, bilishim kerak bo'lgan narsa bormi?", "note": null},
  {"num": 49, "time": "00:03:51,140 --> 00:03:54,099", "arabic": "فَأَنَا ابْنَتُكِ وَزَوْجَةُ مُحَمَّدٍ", "segs": null, "full_uz": "Axir men sizning qizingiz va Muhammadning xotiniman.", "note": null},
  {"num": 50, "time": "00:03:54,099 --> 00:03:59,219", "arabic": "رُبَّمَا سَرَتْ إِلَيَّ عَدْوَى هَوَاجِسِكِ يَا حَمْدَةُ", "segs": null, "full_uz": "Balki sening xavotirlaring menga ham yuqqandir, Hamda.", "note": null},
  {"num": 51, "time": "00:03:59,219 --> 00:04:04,260", "arabic": "قُلْتُ لَكِ فَوِّضِي أَمْرَكِ إِلَى اللَّهِ وَهُوَ حَسْبُنَا", "segs": null, "full_uz": "Senga aytdim-ku, ishingni Allohga topshir, U bizga yetarli.", "note": null},
  {"num": 52, "time": "00:04:04,260 --> 00:04:06,540", "arabic": "اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Hamdlar bo'lsin.", "note": null},
  {"num": 53, "time": "00:04:06,540 --> 00:04:08,560", "arabic": "تَفَضَّلْ يَا عَمَّتِي", "segs": null, "full_uz": "Marhamat, ammajon.", "note": null},
  {"num": 54, "time": "00:04:08,560 --> 00:04:09,659", "arabic": "تَفَضَّلْ", "segs": null, "full_uz": "Marhamat.", "note": null},
  {"num": 55, "time": "00:04:17,180 --> 00:04:37,620", "arabic": "لَا بُدَّ أَنَّهُمْ فِي غَايَةِ الْقَلَقِ عَلَيْهِ", "segs": null, "full_uz": "Ular albatta u haqida juda qattiq xavotirdadirlar.", "note": null},
  {"num": 56, "time": "00:04:37,620 --> 00:04:42,699", "arabic": "وَمَا دُمْتُ لَا أَسْتَطِيعُ الذَّهَابَ إِلَيْهِمْ", "segs": null, "full_uz": "Ularning oldiga bora olmasligim sababli.", "note": null},
  {"num": 57, "time": "00:04:42,699 --> 00:04:45,699", "arabic": "إِلَّا بِإِذْنِ وَلِيِّ أَمْرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mo'minlar hukmdorining izniisiz.", "note": null},
  {"num": 58, "time": "00:04:45,699 --> 00:04:52,259", "arabic": "فَيَجِبُ أَنْ أُرْسِلَ إِلَيْهِمْ رَسُولًا لِيَذْهَبَ قَلَقُهُمْ", "segs": null, "full_uz": "Ularning tashvishi ketishi uchun bir kishi jo'natishim kerak.", "note": null},
  {"num": 59, "time": "00:04:52,259 --> 00:04:58,219", "arabic": "فَقَدْ كَادَ شَوْقِي لَهُمْ يَفْتِكُ بِي", "segs": null, "full_uz": "Ularga bo'lgan sog'inchim meni deyarli halok qilay dedi.", "note": null},
  {"num": 61, "time": "00:05:45,699 --> 00:06:04,800", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 62, "time": "00:06:04,800 --> 00:06:08,919", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 63, "time": "00:06:08,919 --> 00:06:09,719", "arabic": "تَفَضَّلْ", "segs": null, "full_uz": "Marhamat.", "note": null},
  {"num": 64, "time": "00:06:09,719 --> 00:06:14,740", "arabic": "أَهْلًا بِقَاضِي قُضَاةِ بَغْدَادَ مُحَمَّدِ بْنِ الْحَسَنِ الشَّيْبَانِيِّ", "segs": null, "full_uz": "Bag'dodning bosh qozisi Muhammad ibn Hasan ash-Shayboniyga xush kelibsiz.", "note": null},
  {"num": 65, "time": "00:06:14,740 --> 00:06:20,639", "arabic": "أَهْلًا بِكَ أَهْلًا بِكَ أَيُّهَا الشَّافِعِيُّ قَدْ وَجَبَتْ عَلَيْنَا زِيَارَتُكَ", "segs": null, "full_uz": "Xush kelibsiz, xush kelibsiz, ey Shofi'iy, sizga tashrif buyurish bizga vojib edi.", "note": null},
  {"num": 66, "time": "00:06:20,639 --> 00:06:24,519", "arabic": "حَلَلْتَ أَهْلًا وَنَزَلْتَ سَهْلًا يَا أَبَا عَبْدِ اللَّهِ تَفَضَّلْ", "segs": null, "full_uz": "Xush kelibsiz, marhamat qildingiz, Abu Abdulloh, marhamat.", "note": "«حَلَلْتَ أَهْلًا وَنَزَلْتَ سَهْلًا» — mehmonni izzat-hurmat bilan kutib olishda ishlatiladigan an'anaviy ibora."},
  {"num": 67, "time": "00:06:24,519 --> 00:06:31,660", "arabic": "إِلَى مَتَى يَتَغَافَلُ مَوْلَاكَ يَا ابْنَ الرَّبِيعِ عَنْ تَجَاوُزَاتِ أَبْنَاءِ بَرْمَكَ فِي شُؤُونِ الْخِلَافَةِ؟", "segs": null, "full_uz": "Xo'jayiningiz, ey Ibn Rabi, Barmak avlodining xalifalik ishlaridagi haddan oshishlariga qachongacha e'tibor bermay kelaveradi?", "note": null},
  {"num": 68, "time": "00:06:31,660 --> 00:06:38,460", "arabic": "لَا أَدْرِي يَا مَوْلَاتِي إِنَّ أَحَدًا لَا يَقْوَى عَلَى الْحَدِيثِ مَعَ أَمِيرِ الْمُؤْمِنِينَ بِشَأْنِ الْبَرَامِكَةِ", "segs": null, "full_uz": "Bilmayman, xonim, Baramaklar haqida mo'minlar amiri bilan gaplashishga hech kimning kuchi yetmaydi.", "note": null},
  {"num": 69, "time": "00:06:38,460 --> 00:06:43,220", "arabic": "فَأَمِيرُ الْمُؤْمِنِينَ لَا يَرْضَى أَنْ يَنَالَهُمْ أَحَدٌ وَلَوْ بِكَلِمَةٍ تُقَالُ", "segs": null, "full_uz": "Chunki mo'minlar amiri ularga hatto bir og'iz gap bilan ham tegilishiga rozi bo'lmaydi.", "note": null},
  {"num": 70, "time": "00:06:43,220 --> 00:06:46,840", "arabic": "أَمِيرُ الْمُؤْمِنِينَ يَخُوضُ بِعَقْلِهِ وَحِكْمَتِهِ", "segs": null, "full_uz": "Mo'minlar amiri o'z aqli va donoligi bilan ish yuritadi.", "note": null},
  {"num": 71, "time": "00:06:46,840 --> 00:06:51,480", "arabic": "وَلَا يَرْضَى أَنْ يَتَوَغَّلَ أَحَدٌ فِي شُؤُونِ الْحُكْمِ وَالْخِلَافَةِ مَهْمَا كَانَ", "segs": null, "full_uz": "Va hech kim, kim bo'lishidan qat'i nazar, hukm va xalifalik ishlariga chuqur aralashishiga rozi bo'lmaydi.", "note": null},
  {"num": 72, "time": "00:06:51,480 --> 00:06:54,920", "arabic": "فَزِمَامُ الدَّوْلَةِ كُلُّهَا فِي يَدِهِ", "segs": null, "full_uz": "Davlatning butun jilovi uning qo'lida.", "note": null},
  {"num": 73, "time": "00:06:54,920 --> 00:06:58,200", "arabic": "وَلَكِنْ آلَ بَرْمَكَ قَدْ بَلَغُوا مِنَ الْأَمْرِ غَايَتَهُ", "segs": null, "full_uz": "Lekin Barmak avlodi bu ishda haddan oshib ketishdi.", "note": null},
  {"num": 74, "time": "00:06:58,200 --> 00:07:03,540", "arabic": "فَقَدِ اسْتَأْثَرُوا لِأَنْفُسِهِمْ وَأَتْبَاعِهِمْ بِمُقَدَّرَاتِ الدَّوْلَةِ وَشُؤُونِهَا", "segs": null, "full_uz": "Ular davlat taqdirlari va ishlarini o'zlari va tarafdorlariga ajratib olishdi.", "note": null},
  {"num": 75, "time": "00:07:03,540 --> 00:07:09,540", "arabic": "وَلَيْسَ أَدَلَّ عَلَى ذَلِكَ مِنْ أَنَّ نَفَقَةَ الْبَرَامِكَةِ تَفُوقُ نَفَقَةَ أَمِيرِ الْمُؤْمِنِينَ نَفْسِهِ", "segs": null, "full_uz": "Bunga eng aniq dalil — Baramaklarning xarajati mo'minlar amirining o'zining xarajatidan ham oshib ketishidir.", "note": null},
  {"num": 76, "time": "00:07:09,540 --> 00:07:15,120", "arabic": "ثُمَّ هَاهُمُ الْآنَ يَلْتَفُّونَ حَوْلَ ابْنِهِ عَبْدِ اللَّهِ الْمَأْمُونِ", "segs": null, "full_uz": "Endi esa mana, uning o'g'li Abdulloh Ma'mun atrofida to'planishyapti.", "note": null},
  {"num": 77, "time": "00:07:15,120 --> 00:07:18,060", "arabic": "اِلْتِفَافَ الْحَيَّةِ عَلَى فَرَائِسِهَا", "segs": null, "full_uz": "Ilonning o'ljasi atrofida chirmashib olishidek.", "note": null},
  {"num": 78, "time": "00:07:18,060 --> 00:07:23,000", "arabic": "وَأَخْشَى أَنَّ هُنَاكَ مَنْ يَكِيدُ فِي الْخَفَاءِ", "segs": null, "full_uz": "Va yashirincha fitna uyushtirayotgan birov bordan qo'rqaman.", "note": null},
  {"num": 79, "time": "00:07:23,000 --> 00:07:25,680", "arabic": "يَا مَوْلَاةَ زُبَيْدَةَ", "segs": null, "full_uz": "Ey Zubayda xonim.", "note": null},
  {"num": 80, "time": "00:07:25,680 --> 00:07:28,720", "arabic": "إِنَّ دَوْلَةَ الْخِلَافَةِ فِي خَطَرٍ", "segs": null, "full_uz": "Xalifalik davlati xavf ostida.", "note": null},
  {"num": 81, "time": "00:07:28,720 --> 00:07:33,759", "arabic": "أُثَنِّي عَلَى كَلَامِ ابْنِ الرَّبِيعِ يَا مَوْلَاةَ", "segs": null, "full_uz": "Ibn Rabining gapini tasdiqlayman, xonim.", "note": null},
  {"num": 82, "time": "00:07:33,759 --> 00:07:38,020", "arabic": "بِأَنَّهُمْ أَحَاطُوا الْمَأْمُونَ بِأَعْوَانِهِمْ وَعُيُونِهِمْ", "segs": null, "full_uz": "Ular Ma'munni o'z yordamchilari va josuslari bilan o'rab olishgan.", "note": null},
  {"num": 83, "time": "00:07:38,019 --> 00:07:43,039", "arabic": "وَلَا سِيَّمَا ذَلِكَ الدَّاهِيَةُ الْمُسَمَّى الْفَضْلَ بْنَ سَهْلٍ", "segs": null, "full_uz": "Ayniqsa, o'sha ayyor, Fazl ibn Sahl deb ataladigan kishi.", "note": null},
  {"num": 84, "time": "00:07:43,039 --> 00:07:44,779", "arabic": "اِسْمَعْ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Eshit, Abul-Abbos.", "note": null},
  {"num": 85, "time": "00:07:44,779 --> 00:07:47,500", "arabic": "كُلُّ آذَانٍ مُصْغِيَةٌ يَا مَوْلَاتِي", "segs": null, "full_uz": "Barcha quloqlar diqqat bilan tinglashga tayyor, xonim.", "note": null},
  {"num": 86, "time": "00:07:47,500 --> 00:07:51,579", "arabic": "إِنْ كَانَتِ الْأُمُورُ كَمَا ذَكَرْتُمْ فَإِنَّ ذَلِكَ لَا يُنْبِئُ بِخَيْرٍ", "segs": null, "full_uz": "Agar ishlar aytganingizdek bo'lsa, bu yaxshilikdan darak bermaydi.", "note": null},
  {"num": 87, "time": "00:07:51,579 --> 00:07:56,500", "arabic": "وَيَجِبُ أَنْ نَجِدَ حَلًّا بِسُرْعَةٍ قَبْلَ أَنْ تَغْرَقَ السَّفِينَةُ", "segs": null, "full_uz": "Kema cho'kib ketishidan oldin tezda yechim topishimiz kerak.", "note": null},
  {"num": 88, "time": "00:07:57,319 --> 00:08:00,680", "arabic": "لَا أَكُفُّ عَنِ التَّفْكِيرِ وَالتَّدْبِيرِ يَا مَوْلَاتِي", "segs": null, "full_uz": "O'ylash va reja tuzishni to'xtatmayapman, xonim.", "note": null},
  {"num": 89, "time": "00:08:00,680 --> 00:08:07,339", "arabic": "وَلَكِنْ لَا سَبِيلَ عَلَيْهِمْ وَهُمْ عَلَى مَكَانَتِهِمْ عِنْدَ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Lekin ular mo'minlar amiri nazdida shu maqomda turar ekan, ularga qarshi hech qanday yo'l yo'q.", "note": null},
  {"num": 90, "time": "00:08:07,339 --> 00:08:13,899", "arabic": "وَلَكِنَّ الْفَضْلَ ابْنَ الرَّبِيعِ قَدْ قَطَعَ عَلَى نَفْسِهِ عَهْدًا بِأَنْ يَسْتَأْصِلَ شَأْفَتَهُمْ", "segs": null, "full_uz": "Lekin Fazl ibn Rabi ularning ildizini butunlay yo'q qilishga o'ziga va'da bergan.", "note": null},
  {"num": 91, "time": "00:08:13,899 --> 00:08:17,299", "arabic": "لَا تَنْقُصُكَ الْحِيلَةُ وَالدَّهَاءُ يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Sizda hiyla va ayyorlik yetarli, Ibn Rabi.", "note": null},
  {"num": 92, "time": "00:08:17,299 --> 00:08:19,719", "arabic": "فَامْضِ فِيمَا تَرَى وَتَعْزِمُ", "segs": null, "full_uz": "Ko'rgan va qat'iy qaror qilgan narsangizni amalga oshiring.", "note": null},
  {"num": 93, "time": "00:08:19,719 --> 00:08:24,620", "arabic": "وَاعْلَمْ أَنَّ مَوْلَاتَكَ زُبَيْدَةَ تَرْعَاكَ وَتَحْمِيكَ", "segs": null, "full_uz": "Va bilingki, xo'jayiningiz Zubayda sizni asraydi va himoya qiladi.", "note": null},
  {"num": 94, "time": "00:08:24,620 --> 00:08:26,899", "arabic": "فَلَا تَخْشَ شَيْئًا", "segs": null, "full_uz": "Hech narsadan qo'rqmang.", "note": null},
  {"num": 95, "time": "00:08:26,899 --> 00:08:27,659", "arabic": "إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa.", "note": null},
  {"num": 96, "time": "00:08:27,659 --> 00:08:35,220", "arabic": "إِذَنْ فَقَدْ تَصَافَى الْوُدُّ بَيْنَكُمْ يَا شَافِعِيُّ", "segs": null, "full_uz": "Demak, sizlar orangizdagi mehr-oqibat tiklandi, ey Shofi'iy.", "note": null},
  {"num": 97, "time": "00:08:35,220 --> 00:08:38,960", "arabic": "تَقْصِدُ أَمِيرَ الْمُؤْمِنِينَ هَارُونَ؟", "segs": null, "full_uz": "Mo'minlar amiri Horunni nazarda tutyapsizmi?", "note": null},
  {"num": 98, "time": "00:08:38,960 --> 00:08:42,180", "arabic": "أَجَلْ فِيمَا يَبْدُو", "segs": null, "full_uz": "Ha, shundaydek ko'rinadi.", "note": null},
  {"num": 99, "time": "00:08:42,180 --> 00:08:48,740", "arabic": "وَإِنْ كُنْتُ أَعْتِبُ عَلَيْهِ لِحِرْمَانِي مِنَ الْقُفُولِ إِلَى مَكَّةَ حَمَاهَا اللَّهُ فِي الْوَقْتِ الرَّاهِنِ", "segs": null, "full_uz": "Garchi hozirgi vaqtda meni Makka — Alloh uni asrasin — ga qaytishdan mahrum qilgani uchun undan xafaman.", "note": null},
  {"num": 100, "time": "00:08:48,740 --> 00:08:53,240", "arabic": "لَعَلَّهُ يُرِيدُ أَنْ يَسْتَأْنِسَ بِكَ يَا أَبَا مُحَمَّدٍ", "segs": null, "full_uz": "Balki u siz bilan suhbatlashib xotirjam bo'lishni istaydi, Abu Muhammad.", "note": null},
  {"num": 101, "time": "00:08:53,240 --> 00:08:56,960", "arabic": "أَوْ يَنْتَفِعُ مِنْ عِلْمِكَ وَفِقْهِكَ وَحَصَافَةِ رَأْيِكَ", "segs": null, "full_uz": "Yoki ilmingiz, fiqhingiz va fikringizning puxtaligidan foydalanmoqchidir.", "note": null},
  {"num": 102, "time": "00:09:00,740 --> 00:09:00,740", "arabic": "لَا لَا لَا لَا أَظُنُّ ذَلِكَ", "segs": null, "full_uz": "Yo'q, yo'q, yo'q, bunday deb o'ylamayman.", "note": null},
  {"num": 103, "time": "00:09:00,740 --> 00:09:08,220", "arabic": "إِنَّ الرَّشِيدَ وَإِنْ ظَهَرَتْ لَهُ بَرَاءَتِي مِمَّا نُسِبَ إِلَيَّ كَذِبًا مِنْ أَمْرِ الْخُرُوجِ عَلَيْهِ", "segs": null, "full_uz": "Rashid, garchi unga men haqimda yolg'on to'qilgan — unga qarshi chiqish haqidagi — aybdan pokligim ayon bo'lgan bo'lsa ham.", "note": null},
  {"num": 104, "time": "00:09:08,220 --> 00:09:14,360", "arabic": "إِلَّا أَنَّهُ مَا زَالَ يَتَوَجَّسُ خِيفَةً مِنْ هَذَا الزَّعْمِ وَالِادِّعَاءِ", "segs": null, "full_uz": "shunga qaramay, u hali ham bu da'vodan xavotirlanib turibdi.", "note": null},
  {"num": 105, "time": "00:09:14,360 --> 00:09:18,080", "arabic": "وَكَيْفَ ذَلِكَ يَا ابْنَ إِدْرِيسَ؟", "segs": null, "full_uz": "Bu qanday bo'lishi mumkin, ey Ibn Idris?", "note": null},
  {"num": 106, "time": "00:09:18,080 --> 00:09:22,200", "arabic": "أَنْتَ تَعْلَمُ أَنَّ بَنِي الْعَبَّاسِ مُنْذُ تَسَلُّمِهِمْ مَقَالِيدَ الْخِلَافَةِ", "segs": null, "full_uz": "Bilasizki, Abbosiylar xalifalik jilovini qo'lga olganlaridan beri.", "note": null},
  {"num": 107, "time": "00:09:22,200 --> 00:09:28,860", "arabic": "وَهُمْ لِلْأَسَفِ فِي خِصَامٍ دَائِمٍ مَعَ أَبْنَاءِ عُمُومَتِهِمُ الطَّالِبِيِّينَ", "segs": null, "full_uz": "Afsuski, amakivachchalari Tolibiylar bilan doimiy nizoda.", "note": null},
  {"num": 108, "time": "00:09:28,860 --> 00:09:35,460", "arabic": "أَعْلَمُ ذَلِكَ فَالطَّالِبِيُّونَ كَانُوا قَدْ سَاعَدُوهُمْ فِي إِنْهَاءِ دَوْلَةِ بَنِي أُمَيَّةَ", "segs": null, "full_uz": "Bilaman, Tolibiylar Umaviylar davlatini tugatishda ularga yordam bergan edilar.", "note": null},
  {"num": 109, "time": "00:09:35,460 --> 00:09:39,460", "arabic": "ثُمَّ لَمَّا اسْتَأْثَرَ بَنُو الْعَبَّاسِ بِالْحُكْمِ دُونَهُمْ", "segs": null, "full_uz": "So'ngra Abbosiylar hokimiyatni ulardan mahrum qilib, o'zlariga ajratib olganlarida.", "note": null},
  {"num": 110, "time": "00:09:39,460 --> 00:09:42,180", "arabic": "دَبَّ الْخِلَافُ بَيْنَ أَبْنَاءِ الْبَيْتَيْنِ", "segs": null, "full_uz": "Ikki xonadon farzandlari orasida ixtilof paydo bo'ldi.", "note": null},
  {"num": 111, "time": "00:09:42,180 --> 00:09:50,300", "arabic": "وَقَدْ عَانَى مِنْ وَيْلَاتِ ذَلِكَ الْخَلِيفَةُ الْمَنْصُورُ وَالْخَلِيفَةُ الْمَهْدِيُّ وَالْخَلِيفَةُ الْهَادِي", "segs": null, "full_uz": "Bundan xalifa Mansur, xalifa Mahdiy va xalifa Hodiy azob chekkan edilar.", "note": null},
  {"num": 112, "time": "00:09:50,300 --> 00:09:54,759", "arabic": "حَتَّى هَارُونَ الرَّشِيدَ لَمْ تَمُرَّ عَلَيْهِ سَنَةٌ", "segs": null, "full_uz": "Hatto Horun ar-Rashidning o'ziga ham bir yil o'tmagan.", "note": null},
  {"num": 113, "time": "00:09:54,759 --> 00:09:59,200", "arabic": "إِلَّا وَكَدَّرَ صَفْوَهَا نِزَاعٌ مَعَ أَحَدِ أَبْنَاءِ الْبَيْتِ الطَّالِبِيِّ", "segs": null, "full_uz": "Tolibiy xonadonining bir farzandi bilan nizo uni bulg'amasin.", "note": null},
  {"num": 114, "time": "00:09:59,200 --> 00:10:05,019", "arabic": "وَهَذَا يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ حَسَنٍ يَقْبَعُ فِي أَحَدِ سُجُونِ الْبَرَامِكَةِ", "segs": null, "full_uz": "Mana, Yahyo ibn Abdulloh ibn Hasan Baramaklarning bir zindonida yotibdi.", "note": null},
  {"num": 115, "time": "00:10:05,019 --> 00:10:05,840", "arabic": "جَرَّاءَ ذَلِكَ", "segs": null, "full_uz": "Shu sababdan.", "note": null},
  {"num": 116, "time": "00:10:05,840 --> 00:10:08,679", "arabic": "تَمَامًا تَمَامًا يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Aynan shunday, aynan shunday, Abu Abdulloh.", "note": null},
  {"num": 117, "time": "00:10:08,679 --> 00:10:15,840", "arabic": "فَلَمَّا كَانَ أَبْنَاءُ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ هُمْ أَبْنَاءَ عُمُومَتِي", "segs": null, "full_uz": "Ali ibn Abu Tolib — Alloh undan rozi bo'lsin — farzandlari mening amakivachchalarim bo'lgani uchun.", "note": null},
  {"num": 118, "time": "00:10:15,840 --> 00:10:18,720", "arabic": "وَفِي ذَاتِ الْوَقْتِ هُمْ أَبْنَاءُ عُمُومَتِهِ", "segs": null, "full_uz": "Va shu bilan birga, ularning ham amakivachchalari.", "note": null},
  {"num": 119, "time": "00:10:18,720 --> 00:10:23,039", "arabic": "فَهُوَ يَخْشَى أَنْ أَكُونَ قَدْ مِلْتُ إِلَيْهِمْ وَلَوْ بِمَحْضِ الْكَلَامِ", "segs": null, "full_uz": "U hatto sof so'z bilan bo'lsa ham, men ularga moyil bo'lib qolganimdan qo'rqadi.", "note": null},
  {"num": 120, "time": "00:10:23,039 --> 00:10:27,740", "arabic": "أَنْتَ تَعْلَمُ أَنَّ اللِّسَانَ أَمْضَى مِنَ السِّنَانِ", "segs": null, "full_uz": "Bilasizki, til nayzadan ham o'tkirroqdir.", "note": null},
  {"num": 121, "time": "00:10:27,740 --> 00:10:33,620", "arabic": "فَهِمْتُ مَا تَرْمِي إِلَيْهِ أَيُّهَا الشَّافِعِيُّ", "segs": null, "full_uz": "Nimani nazarda tutayotganingizni tushundim, ey Shofi'iy.", "note": null},
  {"num": 122, "time": "00:10:33,620 --> 00:10:39,980", "arabic": "فَالرَّشِيدُ يَسْجُنُ حُرِّيَّتَكَ وَيُقَيِّدُ حَرَكَتَكَ", "segs": null, "full_uz": "Demak, Rashid ozodligingizni qamayapti va harakatingizni cheklayapti.", "note": null},
  {"num": 123, "time": "00:10:39,980 --> 00:10:42,599", "arabic": "وَذَلِكَ بَعْدَ أَنْ ظَهَرَتْ لَهُ بَرَاءَتُكَ", "segs": null, "full_uz": "Bu esa pokligingiz unga ma'lum bo'lgandan keyin.", "note": null},
  {"num": 124, "time": "00:10:42,599 --> 00:10:44,919", "arabic": "دَرْءًا لِاحْتِمَالٍ بَسِيطٍ", "segs": null, "full_uz": "Oddiy bir ehtimoldan saqlanish uchun.", "note": null},
  {"num": 125, "time": "00:10:44,919 --> 00:10:48,219", "arabic": "هَذَا مَا قَصَدْتُهُ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Aynan shuni nazarda tutgan edim, Abu Abdulloh.", "note": null},
  {"num": 126, "time": "00:10:48,220 --> 00:10:53,899", "arabic": "إِذَنْ عَلَيَّ أَنْ أُقَدِّمَ شُكْرِي لِأَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Demak, mo'minlar amiriga minnatdorchiligimni bildirishim kerak.", "note": null},
  {"num": 127, "time": "00:10:53,899 --> 00:10:56,040", "arabic": "أَنِ اسْتَبْقَاكَ هُنَا فِي بَغْدَادَ", "segs": null, "full_uz": "Sizni bu yerda, Bag'dodda qoldirgani uchun.", "note": null},
  {"num": 128, "time": "00:10:56,040 --> 00:10:58,879", "arabic": "حَتَّى نَأْنَسَ بِصُحْبَتِكَ يَا أَبَا مُحَمَّدٍ", "segs": null, "full_uz": "Sizning suhbatingizdan bahramand bo'lishimiz uchun, Abu Muhammad.", "note": null},
  {"num": 129, "time": "00:10:58,879 --> 00:11:05,259", "arabic": "تَأْنَسُ أَنْتَ بِصُحْبَتِي وَتَتَجَرَّعُ أُمِّي وَأَهْلِي مَرَارَةَ الْفُرْقَةِ", "segs": null, "full_uz": "Siz mening suhbatimdan bahramand bo'lasiz-u, onam va yaqinlarim esa ayriliq achchig'ini totadilar.", "note": null},
  {"num": 130, "time": "00:11:18,220 --> 00:11:32,080", "arabic": "اَلسَّلَامُ عَلَيْكَ يَا أَحْمَدُ", "segs": null, "full_uz": "Sizga salom bo'lsin, Ahmad.", "note": null},
  {"num": 131, "time": "00:11:32,080 --> 00:11:33,600", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 132, "time": "00:11:33,600 --> 00:11:34,980", "arabic": "أَهْلًا بِكِ يَا خَالَةُ", "segs": null, "full_uz": "Xush kelibsiz, xolajon.", "note": null},
  {"num": 133, "time": "00:11:34,980 --> 00:11:37,180", "arabic": "لِي حَاجَةٌ عِنْدَكَ يَا وَلَدِي", "segs": null, "full_uz": "Sendan bir iltimosim bor, o'g'lim.", "note": null},
  {"num": 134, "time": "00:11:37,180 --> 00:11:39,320", "arabic": "تَفَضَّلِي فَأُمِّي دَاخِلَ الْبَيْتِ", "segs": null, "full_uz": "Marhamat, onam uyda.", "note": null},
  {"num": 135, "time": "00:11:39,320 --> 00:11:40,600", "arabic": "ثُمَّ نَنْظُرْ لَكِ حَاجَتَكِ", "segs": null, "full_uz": "So'ngra iltimosingizga qaraymiz.", "note": null},
  {"num": 136, "time": "00:11:40,600 --> 00:11:42,480", "arabic": "لَنْ أَدْخُلَ إِلَى الْبَيْتِ", "segs": null, "full_uz": "Uyga kirmayman.", "note": null},
  {"num": 137, "time": "00:11:42,480 --> 00:11:45,440", "arabic": "قَبْلَ أَنْ تَعِدَنِي أَنْ تُلَبِّيَ حَاجَتِي", "segs": null, "full_uz": "Iltimosimni bajarishga va'da bermaguningcha.", "note": null},
  {"num": 138, "time": "00:11:45,440 --> 00:11:46,720", "arabic": "حَسَنًا حَسَنًا", "segs": null, "full_uz": "Xo'p, xo'p.", "note": null},
  {"num": 139, "time": "00:11:46,720 --> 00:11:49,460", "arabic": "تَفَضَّلِي وَإِنْ شَاءَ اللَّهُ لَنْ تَخْرُجِي إِلَّا رَاضِيَةً", "segs": null, "full_uz": "Marhamat, Alloh xohlasa, faqat rozi bo'lgan holda chiqasiz.", "note": null},
  {"num": 140, "time": "00:11:49,460 --> 00:11:50,040", "arabic": "تَفَضَّلِي", "segs": null, "full_uz": "Marhamat.", "note": null},
  {"num": 141, "time": "00:11:50,040 --> 00:12:00,940", "arabic": "مَاذَا؟ أَصَابَكَ الْعَمَى؟", "segs": null, "full_uz": "Nima? Ko'zing ko'r bo'lib qoldimi?", "note": null},
  {"num": 142, "time": "00:12:00,940 --> 00:12:02,139", "arabic": "لِمَاذَا لَا تَسْكُتِينَ؟", "segs": null, "full_uz": "Nega jim turmaysan?", "note": null},
  {"num": 143, "time": "00:12:02,139 --> 00:12:05,720", "arabic": "اُسْكُتِي، أَلَا تَرَيْنَنِي لَا يَقِرُّ لِي قَرَارٌ وَلَا يَهْدَأُ لِي بَالٌ؟", "segs": null, "full_uz": "Jim bo'l, ko'rmayapsanmi, men xotirjam bo'lolmayapman, ko'nglim tinchimayapti?", "note": null},
  {"num": 144, "time": "00:12:05,720 --> 00:12:10,840", "arabic": "كَيْفَ يَرَى أَمَامَهُ مَنْ أَفْقَدَهُ الْقَلَقُ صَبْرَهُ وَأَضَلَّهُ طَرِيقَهُ؟ كَيْفَ؟", "segs": null, "full_uz": "Sabrini yo'qotib, yo'lini yo'qotgan kishi qanday qilib old-ortini ko'ra oladi? Qanday?", "note": null},
  {"num": 145, "time": "00:12:10,840 --> 00:12:15,820", "arabic": "إِذَنْ لِمَاذَا لَا تَجْلِسُ فِي مَكَانٍ مَا وَتَقْلَقُ كَمْ تَشَاءُ وَتَدَعُنِي أَعْمَلُ؟", "segs": null, "full_uz": "Unda nega bir joyda o'tirib, xohlagancha xavotir olib, meni ishlashga qo'ymaysan?", "note": null},
  {"num": 146, "time": "00:12:15,820 --> 00:12:19,540", "arabic": "لِمَ لَا تَسْكُتِينَ وَتَدَعِينِي أَقْلَقُ عَلَى رَاحَتِي؟", "segs": null, "full_uz": "Nega sen jim bo'lib, meni o'z osoyishtaligim uchun xavotirlanishimga qo'ymaysan?", "note": null},
  {"num": 147, "time": "00:12:19,540 --> 00:12:23,240", "arabic": "مُنْذُ الْأَمْسِ وَأَنْتَ عَلَى هَذِهِ الْحَالِ", "segs": null, "full_uz": "Kechadan beri shu holatdasan.", "note": null},
  {"num": 148, "time": "00:12:23,240 --> 00:12:25,820", "arabic": "سَنُصَابُ كُلُّنَا بِعَدْوَاكَ وَقَلَقِكَ", "segs": null, "full_uz": "Hammamiz sening xavotiring va tashvishing yuqtirib olamiz.", "note": null},
  {"num": 149, "time": "00:12:25,820 --> 00:12:29,560", "arabic": "ثُمَّ قُلْ لِي هَلْ سَتَنْقَلِبُ الدُّنْيَا إِنْ تَرَكْتَ الدُّكَّانَ؟", "segs": null, "full_uz": "Ayt-chi, do'konni tashlab qo'ysang, dunyo ostin-ustun bo'lib ketadimi?", "note": null},
  {"num": 150, "time": "00:12:29,560 --> 00:12:33,940", "arabic": "سَلَمَةُ زَوْجَتِي أُمُّ عُمَيْرٍ هَلْ سَتُفْلِحُ أُمِّي فِي مَسْعَاهَا؟", "segs": null, "full_uz": "Salama, xotinim, Umayrning onasi — onam o'z sa'y-harakatida muvaffaqiyat qozonarmikan?", "note": null},
  {"num": 151, "time": "00:12:33,940 --> 00:12:36,940", "arabic": "وَهَلْ تَعْجِزُ أُمُّكَ عَنْ فِعْلِ شَيْءٍ؟", "segs": null, "full_uz": "Onang biror ishni qila olmay qolganmidi?", "note": null},
  {"num": 152, "time": "00:12:36,940 --> 00:12:39,820", "arabic": "أَلَا يَكْفِي أَنَّهَا أَفْلَحَتْ فِي تَزْوِيجِي بِكِ؟", "segs": null, "full_uz": "Meni senga uylantirishga muvaffaq bo'lgani yetarli emasmi?", "note": null},
  {"num": 153, "time": "00:12:45,820 --> 00:12:57,740", "arabic": "مَا الْأَخْبَارُ يَا أُمِّي؟", "segs": null, "full_uz": "Xabarlar qanday, onajon?", "note": null},
  {"num": 154, "time": "00:12:57,740 --> 00:12:59,879", "arabic": "اَلْأَخْبَارُ جَيِّدَةٌ أَيُّهَا الْإِسْكَافِيُّ", "segs": null, "full_uz": "Xabarlar yaxshi, ey etikdo'z.", "note": null},
  {"num": 155, "time": "00:12:59,879 --> 00:13:03,720", "arabic": "وَلَكِنْ دَعْنِي أَلْتَقِطْ أَنْفَاسِي فَقَدْ أَتْعَبَنِي طُولُ الطَّرِيقِ", "segs": null, "full_uz": "Lekin nafasimni rostlab olay, yo'lning uzunligi meni charchatdi.", "note": null},
  {"num": 156, "time": "00:13:03,720 --> 00:13:07,260", "arabic": "وَأَنَا يَا أُمِّي طُولُ مُكُوثِي فِي الْبَيْتِ أَضْجَرَنِي", "segs": null, "full_uz": "Men esa, onajon, uyda uzoq o'tirishim meni zeriktirib yubordi.", "note": null},
  {"num": 157, "time": "00:13:07,260 --> 00:13:10,820", "arabic": "يَعْنِي مَا الْخَبَرُ؟ أَخْبِرِينِي هَلْ وَافَقَ؟", "segs": null, "full_uz": "Xo'sh, xabar nima? Ayt-chi, u rozi bo'ldimi?", "note": null},
  {"num": 158, "time": "00:13:11,720 --> 00:13:14,580", "arabic": "عَدِمَتْكَ أُمُّكَ يَا عَامِرُ قُلْ مَعِي آمِينَ", "segs": null, "full_uz": "Onang seni yo'qotsin, Omir! Men bilan birga 'omin' de.", "note": "Hazil-mutoyiba ohangida g'azab bildirish uchun ishlatiladigan qarg'ish ibora."},
  {"num": 159, "time": "00:13:14,580 --> 00:13:15,580", "arabic": "آمِينَ", "segs": null, "full_uz": "Omin.", "note": null},
  {"num": 160, "time": "00:13:15,580 --> 00:13:18,500", "arabic": "وَافَقَ ابْنُ حَنْبَلٍ أَنْ تَعُودَ إِلَى الدُّكَّانِ", "segs": null, "full_uz": "Ibn Hanbal do'konga qaytishingga rozi bo'ldi.", "note": null},
  {"num": 161, "time": "00:13:18,500 --> 00:13:22,080", "arabic": "شَرِيطَةَ أَنْ لَا تَعُودَ لِذِكْرِ بَيْعِهَا أَوْ شِرَائِهَا", "segs": null, "full_uz": "Shart shuki, uni sotish yoki sotib olish haqida boshqa gapirmasang.", "note": null},
  {"num": 162, "time": "00:13:22,080 --> 00:13:27,340", "arabic": "اَلْحَمْدُ لِلَّهِ اَلْحَمْدُ لِلَّهِ اَلْحَمْدُ لِلَّهِ اَلْحَمْدُ لِلَّهِ يَا أُمِّي", "segs": null, "full_uz": "Hamdlar bo'lsin, hamdlar bo'lsin, hamdlar bo'lsin, hamdlar bo'lsin, onajon!", "note": null},
  {"num": 163, "time": "00:13:27,340 --> 00:13:31,139", "arabic": "أُمِّي قُولِي لَهُ أَنَّنِي لَنْ أَعُودَ لِذِكْرِ ذَلِكَ أَبَدًا", "segs": null, "full_uz": "Onajon, unga aytingki, men bu haqda boshqa hech qachon gapirmayman.", "note": null},
  {"num": 164, "time": "00:13:31,139 --> 00:13:36,340", "arabic": "تُرِيدُنِي أَنْ أَعُودَ لَهُ وَأَقُولَ لَهُ مَا قُلْتَ؟", "segs": null, "full_uz": "Uning oldiga qaytib, aytganingni aytishimni xohlaysanmi?", "note": null},
  {"num": 165, "time": "00:13:36,340 --> 00:13:37,420", "arabic": "أَحْمَقٌ أَنْتَ", "segs": null, "full_uz": "Ahmoqsan sen.", "note": null},
  {"num": 166, "time": "00:13:37,420 --> 00:13:38,840", "arabic": "اِنْتَهَى الْأَمْرُ", "segs": null, "full_uz": "Ish tugadi.", "note": null},
  {"num": 167, "time": "00:13:38,840 --> 00:13:40,580", "arabic": "تَعُودُ إِلَى الدُّكَّانِ", "segs": null, "full_uz": "Do'konga qaytasan.", "note": null},
  {"num": 168, "time": "00:13:40,580 --> 00:13:43,379", "arabic": "وَابْنُ حَنْبَلٍ لَا يَحْتَاجُ إِلَى وُعُودٍ مِنْكَ", "segs": null, "full_uz": "Ibn Hanbalga sendan va'dalar kerak emas.", "note": null},
  {"num": 169, "time": "00:13:43,379 --> 00:13:49,159", "arabic": "أَلَمْ أَقُلْ لَكَ يَا عَامِرُ؟ إِنَّ أُمَّ عَامِرٍ لَا تَعْجِزُ عَنْ شَيْءٍ تُلِحُّ عَلَيْهِ", "segs": null, "full_uz": "Senga aytmaganmidim, Omir? Umm Omir qat'iyat bilan intilgan narsasidan orqaga chekinmaydi.", "note": null},
  {"num": 170, "time": "00:13:49,159 --> 00:13:51,519", "arabic": "لَكِنَّهُ اشْتَرَطَ شَرْطًا آخَرَ", "segs": null, "full_uz": "Lekin u yana bir shart qo'ydi.", "note": null},
  {"num": 171, "time": "00:13:51,519 --> 00:13:57,279", "arabic": "اِشْتَرَطَ شَرْطًا آخَرَ؟ مَا هُوَ الشَّرْطُ الَّذِي اشْتَرَطَهُ أَحْمَدُ؟ قُولِي يَا أُمِّي", "segs": null, "full_uz": "Yana shart qo'ydimi? Ahmad qo'ygan shart nima edi? Ayting, onajon.", "note": null},
  {"num": 172, "time": "00:13:57,279 --> 00:13:59,820", "arabic": "أَنْ تَنْتَظِمَ بِدَفْعِ أُجْرَتِي مَعَ كُلِّ هِلَالٍ", "segs": null, "full_uz": "Har oy ijaramni muntazam to'lashing.", "note": null},
  {"num": 173, "time": "00:13:59,820 --> 00:14:02,659", "arabic": "لَا بَأْسَ مَعَ كُلِّ هِلَالٍ أَفْعَلُ يَا أُمِّي أَفْعَلُ", "segs": null, "full_uz": "Zarari yo'q, har oy shunday qilaman, onajon, qilaman.", "note": null},
  {"num": 174, "time": "00:14:02,659 --> 00:14:05,620", "arabic": "وَلَا تَنْسَ أَنْ تَدْفَعَ لَهُ أُجْرَةَ الْأَشْهُرِ الْمَاضِيَةِ", "segs": null, "full_uz": "Va o'tgan oylarning ijarasini to'lashni unutma.", "note": null},
  {"num": 175, "time": "00:14:05,620 --> 00:14:07,419", "arabic": "زَوْجَتِي أَفْعَلُ لَا بَأْسَ أَفْعَلُ", "segs": null, "full_uz": "Xotinim, qilaman, zarari yo'q, qilaman.", "note": null},
  {"num": 176, "time": "00:14:07,419 --> 00:14:13,439", "arabic": "كُنْتُ أَنَا وَأَخِي عِيسَى فِي الْكُتَّابِ", "segs": null, "full_uz": "Men va akam Iso kuttobda edik.", "note": null},
  {"num": 177, "time": "00:14:13,439 --> 00:14:18,719", "arabic": "وَكُنَّا نَصَارَى عَلَى دِينِ عِيسَى عَلَيْهِ وَعَلَى نَبِيِّنَا السَّلَامُ", "segs": null, "full_uz": "Va biz Iso alayhissalom — u va bizning payg'ambarimizga salom bo'lsin — dinida nasroniy edik.", "note": null},
  {"num": 178, "time": "00:14:18,719 --> 00:14:22,860", "arabic": "وَكَانَ الْمُعَلِّمُ يُعَلِّمُ الصِّبْيَانَ", "segs": null, "full_uz": "Ustoz bolalarga o'rgatardi.", "note": null},
  {"num": 179, "time": "00:14:22,860 --> 00:14:26,679", "arabic": "أَبٌ وَابْنٌ وَرُوحُ قُدُسٍ", "segs": null, "full_uz": "Ota, o'g'il va muqaddas ruh.", "note": "Nasroniylikdagi «Uch birlik» (Trinity) e'tiqodiga ishora."},
  {"num": 180, "time": "00:14:26,679 --> 00:14:31,099", "arabic": "فَكُنْتُ أَعْتَرِضُ عَلَيْهِ وَأَقُولُ بَلْ أَحَدٌ أَحَدٌ", "segs": null, "full_uz": "Men esa unga e'tiroz bildirib, «Yo'q, U yagona-yu yagona», der edim.", "note": null},
  {"num": 181, "time": "00:14:31,099 --> 00:14:35,199", "arabic": "فَيَضْرِبُنِي الْمُعَلِّمُ عَلَى ذَلِكَ ضَرْبًا شَدِيدًا", "segs": null, "full_uz": "Shunga ustoz meni qattiq urardi.", "note": null},
  {"num": 182, "time": "00:14:35,200 --> 00:14:41,540", "arabic": "حَتَّى كَانَ يَوْمٌ ضَرَبَنِي فِيهِ الْمُعَلِّمُ ضَرْبًا مُبَرِّحًا", "segs": null, "full_uz": "Toki bir kun ustoz meni juda qattiq urdi.", "note": null},
  {"num": 183, "time": "00:14:41,540 --> 00:14:47,900", "arabic": "فَفَرَرْتُ عَلَى وَجْهِي يَوْمَهَا فِي بِلَادِ اللَّهِ الْوَاسِعَةِ", "segs": null, "full_uz": "O'sha kuni Allohning keng yurtida yuz burib qochib ketdim.", "note": "«هَرَبَ عَلَى وَجْهِهِ» — maqsadsiz, qayerga borishini bilmay qochish ma'nosidagi ibora."},
  {"num": 184, "time": "00:14:47,900 --> 00:14:51,560", "arabic": "فَخَافَ عَلَيَّ أَهْلِي كَثِيرًا", "segs": null, "full_uz": "Oilam men uchun juda qattiq qo'rqib qoldi.", "note": null},
  {"num": 185, "time": "00:14:51,560 --> 00:14:54,060", "arabic": "وَكَانَتْ أُمِّي تَقُولُ", "segs": null, "full_uz": "Onam esa aytar edi.", "note": null},
  {"num": 186, "time": "00:14:54,060 --> 00:14:57,620", "arabic": "لَئِنْ رَدَّ اللَّهُ عَلَيَّ ابْنِي مَعْرُوفًا", "segs": null, "full_uz": "Agar Alloh o'g'limni menga sog'-salomat qaytarsa.", "note": null},
  {"num": 187, "time": "00:14:57,620 --> 00:15:00,740", "arabic": "لَأَتَّبِعَنَّهُ عَلَى أَيِّ دِينٍ كَانَ", "segs": null, "full_uz": "Albatta uning qaysi dinida bo'lsa ham, unga ergashaman.", "note": null},
  {"num": 188, "time": "00:15:00,740 --> 00:15:05,060", "arabic": "ثُمَّ قَدِمْتُ إِلَيْهِمْ بَعْدَ سِنِينَ عِدَّةٍ", "segs": null, "full_uz": "So'ngra bir necha yildan keyin ularning oldiga qaytdim.", "note": null},
  {"num": 189, "time": "00:15:05,060 --> 00:15:08,539", "arabic": "فَفَرِحَتْ أُمِّي بِلِقَائِي كَثِيرًا", "segs": null, "full_uz": "Onam meni ko'rganidan juda xursand bo'ldi.", "note": null},
  {"num": 190, "time": "00:15:08,539 --> 00:15:10,700", "arabic": "ثُمَّ قَالَتْ لِي", "segs": null, "full_uz": "So'ngra menga aytdi.", "note": null},
  {"num": 191, "time": "00:15:10,700 --> 00:15:12,500", "arabic": "يَا مَعْرُوفُ", "segs": null, "full_uz": "Ey Ma'ruf.", "note": null},
  {"num": 192, "time": "00:15:12,500 --> 00:15:16,259", "arabic": "عَلَى أَيِّ دِينٍ أَنْتَ؟", "segs": null, "full_uz": "Sen qaysi dindasan?", "note": null},
  {"num": 193, "time": "00:15:16,259 --> 00:15:17,740", "arabic": "فَقُلْتُ عَلَى دِينِ الْإِسْلَامِ", "segs": null, "full_uz": "Men: «Islom dinidaman», dedim.", "note": null},
  {"num": 194, "time": "00:15:17,740 --> 00:15:22,120", "arabic": "قَالَتْ تَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ", "segs": null, "full_uz": "U: «Allohdan o'zga iloh yo'qligiga guvohlik berasanmi?» dedi.", "note": null},
  {"num": 195, "time": "00:15:22,120 --> 00:15:25,039", "arabic": "وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ", "segs": null, "full_uz": "Va Muhammad Allohning rasuli ekaniga guvohlik beraman, dedim.", "note": null},
  {"num": 196, "time": "00:15:25,039 --> 00:15:27,539", "arabic": "فَأَسْلَمَتْ أُمِّي", "segs": null, "full_uz": "Shunda onam musulmon bo'ldi.", "note": null},
  {"num": 197, "time": "00:15:27,539 --> 00:15:30,819", "arabic": "ثُمَّ أَسْلَمَ أَبِي وَأَخِي عِيسَى", "segs": null, "full_uz": "So'ngra otam va akam Iso ham musulmon bo'lishdi.", "note": null},
  {"num": 198, "time": "00:15:30,819 --> 00:15:34,299", "arabic": "وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "segs": null, "full_uz": "Barcha olamlarning Robbisi Allohga hamdlar bo'lsin.", "note": null},
  {"num": 199, "time": "00:15:34,299 --> 00:15:39,500", "arabic": "الَّذِي مَنَّ عَلَيَّ وَعَلَى أَهْلِي بِنِعْمَةِ الْإِيمَانِ وَالْإِسْلَامِ", "segs": null, "full_uz": "U menga va oilamga iymon va islom ne'matini in'om qildi.", "note": null},
  {"num": 200, "time": "00:15:39,500 --> 00:15:49,740", "arabic": "مَا بَالُ أُمِّي نَائِمَةً فِي مِثْلِ هَذِهِ السَّاعَةِ؟", "segs": null, "full_uz": "Onam bunday paytda uxlab yotibdi, unga nima bo'ldi?", "note": null},
  {"num": 201, "time": "00:15:49,740 --> 00:15:52,779", "arabic": "أُمِّي، أُمَّ عَامِرٍ", "segs": null, "full_uz": "Onajon, Umm Omir!", "note": null},
  {"num": 202, "time": "00:15:52,779 --> 00:15:54,519", "arabic": "أُمَّ عَامِرٍ", "segs": null, "full_uz": "Umm Omir!", "note": null},
  {"num": 203, "time": "00:15:54,519 --> 00:15:55,519", "arabic": "أُمِّي", "segs": null, "full_uz": "Onajon!", "note": null},
  {"num": 204, "time": "00:15:57,539 --> 00:15:59,620", "arabic": "أُمِّي، أُمَّ عَامِرٍ", "segs": null, "full_uz": "Onajon, Umm Omir!", "note": null},
  {"num": 205, "time": "00:15:59,620 --> 00:16:02,419", "arabic": "أُمَّ عَامِرٍ أَنَا عَامِرٌ وَلَدُكِ", "segs": null, "full_uz": "Umm Omir, men o'g'lingiz Omirman.", "note": null},
  {"num": 206, "time": "00:16:02,419 --> 00:16:03,500", "arabic": "هَيَّا انْهَضِي", "segs": null, "full_uz": "Yur, o'rningdan tur.", "note": null},
  {"num": 207, "time": "00:16:03,500 --> 00:16:06,099", "arabic": "أُمِّي أُمِّي", "segs": null, "full_uz": "Onajon, onajon!", "note": null},
  {"num": 208, "time": "00:16:06,099 --> 00:16:07,699", "arabic": "مَا بِكِ يَا أُمِّي؟", "segs": null, "full_uz": "Sizga nima bo'ldi, onajon?", "note": null},
  {"num": 209, "time": "00:16:07,699 --> 00:16:09,620", "arabic": "يَا وَيْلِي أُمِّي مَاتَتْ", "segs": null, "full_uz": "Voy holimga, onam vafot etdi!", "note": null},
  {"num": 210, "time": "00:16:09,620 --> 00:16:12,219", "arabic": "أُمُّكَ يَا عَامِرُ مَاتَتْ", "segs": null, "full_uz": "Onang, Omir, vafot etdi.", "note": null},
  {"num": 211, "time": "00:16:12,219 --> 00:16:15,159", "arabic": "يَا حَسْرَتِي يَا وَيْلِي", "segs": null, "full_uz": "Voy afsuslar bo'lsin, voy holimga!", "note": null},
  {"num": 212, "time": "00:16:15,159 --> 00:16:18,339", "arabic": "يَا وَيْلِي أُمِّي مَاتَتْ", "segs": null, "full_uz": "Voy holimga, onam vafot etdi!", "note": null},
  {"num": 213, "time": "00:16:18,339 --> 00:16:20,319", "arabic": "يَا سَلَمَةُ أُمِّي مَاتَتْ", "segs": null, "full_uz": "Salama, onam vafot etdi!", "note": null},
  {"num": 214, "time": "00:16:20,319 --> 00:16:22,439", "arabic": "يَا عُمَيْرُ جَدَّتُكَ مَاتَتْ", "segs": null, "full_uz": "Umayr, buving vafot etdi!", "note": null},
  {"num": 215, "time": "00:16:22,439 --> 00:16:23,980", "arabic": "يَا وَيْلِي", "segs": null, "full_uz": "Voy holimga!", "note": null},
  {"num": 216, "time": "00:16:23,980 --> 00:16:26,860", "arabic": "يَا وَيْلِي عَلَيْكَ يَا عَامِرُ", "segs": null, "full_uz": "Voy holingga, Omir!", "note": null},
  {"num": 217, "time": "00:16:26,860 --> 00:16:32,759", "arabic": "أُمِّي مَاتَتْ يَا سَلَمَةُ", "segs": null, "full_uz": "Onam vafot etdi, Salama!", "note": null},
  {"num": 218, "time": "00:16:32,759 --> 00:16:34,879", "arabic": "قُلْ لَهَا يَا عَامِرُ", "segs": null, "full_uz": "Unga ayt, Omir.", "note": null},
  {"num": 219, "time": "00:16:34,879 --> 00:16:36,879", "arabic": "مَا لَكَ تُوَلْوِلُ لَكَ النِّسَاءُ؟", "segs": null, "full_uz": "Senga nima bo'ldi, ayollar sen uchun yig'lab-siqtayapti?", "note": null},
  {"num": 220, "time": "00:16:36,879 --> 00:16:39,120", "arabic": "مَوْتُهَا أَرْوَحُ لَهُ وَلِغَيْرِهَا", "segs": null, "full_uz": "Uning o'limi u uchun ham, boshqalar uchun ham yengillikdir.", "note": null},
  {"num": 221, "time": "00:16:39,120 --> 00:16:41,379", "arabic": "يَكْفِيهَا مِنَ الْعُمْرِ مَا عَاشَتْ", "segs": null, "full_uz": "Yashagan umri o'ziga yetarli.", "note": null},
  {"num": 222, "time": "00:16:41,379 --> 00:16:44,159", "arabic": "أَلَمْ يُصْبِحْ عُمْرُهَا مِئَتَيْ سَنَةٍ؟", "segs": null, "full_uz": "Uning yoshi ikki yuz yilga yetib qolmadimi?", "note": null},
  {"num": 223, "time": "00:16:44,159 --> 00:16:46,259", "arabic": "خَسِئْتِ أَيَّتُهَا الْحِرْبَاءُ", "segs": null, "full_uz": "Yo'qol, ey bo'kalamun!", "note": "«حِرْبَاء» — rangini tez-tez o'zgartiradigan jonivor; kishining ikkiyuzlamachiligini kesatish uchun ishlatiladi."},
  {"num": 224, "time": "00:16:46,259 --> 00:16:48,139", "arabic": "خَيَّبَ اللَّهُ ظُنُونَكِ", "segs": null, "full_uz": "Alloh gumonlaringni chippakka chiqarsin.", "note": null},
  {"num": 225, "time": "00:16:48,139 --> 00:16:52,180", "arabic": "أُمِّي أُمِّي أُمِّي يَا سَلَمَةُ", "segs": null, "full_uz": "Onam, onam, onam, Salama!", "note": null},
  {"num": 226, "time": "00:16:52,180 --> 00:16:54,440", "arabic": "اَلْحَمْدُ لِلَّهِ أَحْمَدُكَ يَا رَبِّ", "segs": null, "full_uz": "Hamdlar bo'lsin, Senga hamd aytaman, Robbim.", "note": null},
  {"num": 227, "time": "00:16:54,440 --> 00:16:56,180", "arabic": "أُمِّي لَمْ تَمُتْ يَا سَلَمَةُ", "segs": null, "full_uz": "Onam o'lmadi, Salama!", "note": null},
  {"num": 228, "time": "00:16:56,179 --> 00:16:59,679", "arabic": "لَيْسَ قَبْلَ أَنْ تَمُوتَ زَوْجَتُكَ الْقَبِيحَةُ", "segs": null, "full_uz": "Sening xunuk xotining o'lmaguncha o'lmayman.", "note": null},
  {"num": 229, "time": "00:16:59,679 --> 00:17:01,919", "arabic": "لَا تَمُوتُ الْأَفْعَى مَا لَمْ تُقْتَلْ", "segs": null, "full_uz": "Ilon o'ldirilmaguncha o'lmaydi.", "note": null},
  {"num": 230, "time": "00:17:01,919 --> 00:17:03,519", "arabic": "تُحْسِنُ لَكَ يَا عَامِرُ", "segs": null, "full_uz": "Senga yarashadi, Omir.", "note": null},
  {"num": 231, "time": "00:17:03,519 --> 00:17:08,220", "arabic": "لَنْ أَمُوتَ قَبْلَ أَنْ تَمُوتَ بَغِيضَتُكَ يَا ابْنَةَ الْجَزَّارِ", "segs": null, "full_uz": "Sening jirkanch onang o'lmaguncha men o'lmayman, ey qassob qizi.", "note": null},
  {"num": 232, "time": "00:17:08,220 --> 00:17:12,279", "arabic": "اَلْحَمْدُ لِلَّهِ أُمِّي عَلَى قَيْدِ الْحَيَاةِ", "segs": null, "full_uz": "Hamdlar bo'lsin, onam tirik ekan.", "note": null},
  {"num": 233, "time": "00:17:12,279 --> 00:17:14,019", "arabic": "أَحْمَدُكَ يَا رَبِّ", "segs": null, "full_uz": "Senga hamd aytaman, Robbim.", "note": null},
  {"num": 234, "time": "00:17:14,019 --> 00:17:16,299", "arabic": "أُمِّي ذَهَبَ عَقْلِي خَوْفًا عَلَيْكِ", "segs": null, "full_uz": "Onajon, siz uchun qo'rqqanimdan aqlim ketib qoldi.", "note": null},
  {"num": 235, "time": "00:17:16,299 --> 00:17:19,019", "arabic": "مُتَأَكِّدٌ أَنَّكِ عَلَى قَيْدِ الْحَيَاةِ؟", "segs": null, "full_uz": "Tirikligingizga ishonsam bo'ladimi?", "note": null},
  {"num": 236, "time": "00:17:20,119 --> 00:17:23,200", "arabic": "لَوْلَا أَنِّي سَمِعْتُكَ تَبْكِي عَلَيَّ بِقَلْبٍ صَادِقٍ", "segs": null, "full_uz": "Agar sening sof qalb bilan men uchun yig'laganingni eshitmaganimda.", "note": null},
  {"num": 237, "time": "00:17:23,200 --> 00:17:27,220", "arabic": "لَقُلْتُ إِنَّكَ خَبِيثٌ مِثْلَ زَوْجَتِكَ", "segs": null, "full_uz": "Xotiningga o'xshab yovuz ekansan, deb aytardim.", "note": null},
  {"num": 238, "time": "00:17:27,220 --> 00:17:32,240", "arabic": "ثُمَّ كَيْفَ لَا أَكُونُ عَلَى قَيْدِ الْحَيَاةِ وَأَنَا أُكَلِّمُكَ أَيُّهَا الْأَحْمَقُ؟", "segs": null, "full_uz": "Seni bilan gaplashib turgan ekanman, qanday qilib tirik bo'lmay qolaman, ey ahmoq?", "note": null},
  {"num": 239, "time": "00:17:32,240 --> 00:17:35,100", "arabic": "صَحِيحٌ تُكَلِّمِينِي أُمِّي", "segs": null, "full_uz": "Rost, siz men bilan gaplashyapsiz, onajon.", "note": null},
  {"num": 240, "time": "00:17:35,100 --> 00:17:37,840", "arabic": "رُبَّمَا كَانَتْ هَذِهِ فَوَاقَ الْمَوْتِ", "segs": null, "full_uz": "Balki bu o'lim oldidan tetiklashishdir.", "note": "«فَوَاقُ الْمَوْتِ» — o'lim yaqinlashganda vaqtincha o'ziga kelish holati."},
  {"num": 241, "time": "00:17:37,840 --> 00:17:39,420", "arabic": "فَوَاقُ الْمَوْتِ؟", "segs": null, "full_uz": "O'lim oldidan tetiklashishmi?", "note": null},
  {"num": 242, "time": "00:17:39,420 --> 00:17:39,740", "arabic": "نَعَمْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 243, "time": "00:17:39,740 --> 00:17:40,600", "arabic": "اُغْرُبْ عَنْ وَجْهِي", "segs": null, "full_uz": "Ko'zimga ko'rinma!", "note": null},
  {"num": 245, "time": "00:17:41,700 --> 00:17:43,819", "arabic": "اُغْرُبْ عَنْ وَجْهِي قَبَّحَكَ اللَّهُ", "segs": null, "full_uz": "Ko'zimga ko'rinma, Alloh seni jazolasin!", "note": null},
  {"num": 247, "time": "00:17:45,480 --> 00:17:45,980", "arabic": "اِذْهَبْ", "segs": null, "full_uz": "Bor.", "note": null},
  {"num": 250, "time": "00:17:48,640 --> 00:17:51,840", "arabic": "قَبَّحَكَ اللَّهُ وَقَبَّحَ زَوْجَتَكَ", "segs": null, "full_uz": "Alloh seni ham, xotiningni ham jazolasin!", "note": null},
  {"num": 251, "time": "00:17:51,839 --> 00:17:56,859", "arabic": "أَخْبَرَنَا مَالِكٌ عَنْ صَفْوَانَ بْنِ سُلَيْمٍ", "segs": null, "full_uz": "Bizga Molik, Safvon ibn Sulaym orqali xabar berdi.", "note": null},
  {"num": 252, "time": "00:17:56,859 --> 00:17:59,599", "arabic": "عَنْ عَطَاءِ بْنِ يَسَارٍ", "segs": null, "full_uz": "Ato ibn Yasor orqali.", "note": null},
  {"num": 253, "time": "00:17:59,599 --> 00:18:01,299", "arabic": "عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ", "segs": null, "full_uz": "Abu Sa'id al-Xudriydan.", "note": null},
  {"num": 254, "time": "00:18:01,299 --> 00:18:04,720", "arabic": "أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ", "segs": null, "full_uz": "Rasululloh (sollallohu alayhi va sallam) aytdilar.", "note": null},
  {"num": 255, "time": "00:18:04,720 --> 00:18:08,019", "arabic": "غُسْلُ يَوْمِ الْجُمُعَةِ", "segs": null, "full_uz": "Juma kunining g'usli.", "note": null},
  {"num": 256, "time": "00:18:08,019 --> 00:18:10,500", "arabic": "وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ", "segs": null, "full_uz": "Balog'atga yetgan har bir kishiga vojibdir.", "note": null},
  {"num": 257, "time": "00:18:10,500 --> 00:18:12,819", "arabic": "وَالْأَمْرُ بِالْغُسْلِ", "segs": null, "full_uz": "G'usl haqidagi buyruq.", "note": null},
  {"num": 258, "time": "00:18:12,819 --> 00:18:15,179", "arabic": "يَحْتَمِلُ مَعْنَيَيْنِ", "segs": null, "full_uz": "Ikki ma'noni bildirishi mumkin.", "note": null},
  {"num": 259, "time": "00:18:15,179 --> 00:18:19,299", "arabic": "اَلظَّاهِرُ مِنْهُمَا أَنَّهُ وَاجِبٌ", "segs": null, "full_uz": "Ulardan zohiri — bu vojib ekanligidir.", "note": null},
  {"num": 260, "time": "00:18:19,299 --> 00:18:24,720", "arabic": "فَلَا تُجْزِئُ الطَّهَارَةُ لِصَلَاةِ الْجُمُعَةِ إِلَّا بِالْغُسْلِ", "segs": null, "full_uz": "Juma namozi uchun poklanish faqat g'usl bilangina yetarli bo'ladi.", "note": null},
  {"num": 261, "time": "00:18:24,720 --> 00:18:30,680", "arabic": "كَمَا لَا يُجْزِئُ فِي طَهَارَةِ الْجَنَابَةِ غَيْرُ الْغُسْلِ", "segs": null, "full_uz": "Xuddi janobat poklanishida g'usldan boshqasi yetarli bo'lmaganidek.", "note": null},
  {"num": 262, "time": "00:18:30,680 --> 00:18:36,519", "arabic": "وَيُحْتَمَلُ أَنَّهُ مُسْتَحَبٌّ لِلْأَدَبِ وَالنَّظَافَةِ", "segs": null, "full_uz": "Yoki odob va poklik uchun mustahab bo'lishi ham mumkin.", "note": null},
  {"num": 263, "time": "00:18:36,519 --> 00:18:38,299", "arabic": "وَاللَّهُ أَعْلَمُ", "segs": null, "full_uz": "Alloh bilguvchiroqdir.", "note": null},
  {"num": 264, "time": "00:18:38,299 --> 00:18:46,680", "arabic": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ", "segs": null, "full_uz": "Ey Alloh, Sen pok va hamdlisan, Sendan o'zga iloh yo'qligiga guvohlik beraman, Sendan mag'firat so'rayman va Senga tavba qilaman.", "note": "Majlis yakunida aytiladigan mashhur duo («kaffaratul-majlis»)."},
  {"num": 265, "time": "00:18:46,680 --> 00:18:50,120", "arabic": "ائْذَنُوا لِي أَيُّهَا الْإِخْوَةُ أَسْتَوْدِعُكُمُ اللَّهَ", "segs": null, "full_uz": "Menga ijozat bering, birodarlar, sizlarni Allohga omonat qildim.", "note": null},
  {"num": 266, "time": "00:18:50,120 --> 00:19:08,500", "arabic": "لَوْ تَدْرِي مَا نُحَصِّلُهُ مِنَ الْعِلْمِ بِجُلُوسِنَا مَعَ الشَّيْخَيْنِ الْمَرِيسِيِّ وَابْنِ الْأَشْرَسِ يَا صُهَيْبُ", "segs": null, "full_uz": "Agar bilsang edi, Marisiy va Ibn Ashras — ikki ustoz bilan o'tirishimizdan qancha ilm olayotganimizni, Suhayb.", "note": null},
  {"num": 267, "time": "00:19:08,500 --> 00:19:14,600", "arabic": "أَتَدْرِي أَنَّ شَيْخَنَا الْمَرِيسِيَّ كَانَ مِنْ تَلَامِذَةِ الْإِمَامِ أَبِي يُوسُفَ الْقَاضِي رَحِمَهُ اللَّهُ؟", "segs": null, "full_uz": "Bilasanmi, ustozimiz Marisiy imom Abu Yusuf qozi — Alloh unga rahmat qilsin — ning shogirdlaridan bo'lgan?", "note": null},
  {"num": 268, "time": "00:19:14,599 --> 00:19:18,559", "arabic": "أَحَقًّا مَا تَقُولُ؟", "segs": null, "full_uz": "Aytganing rostmi?", "note": null},
  {"num": 269, "time": "00:19:18,559 --> 00:19:22,259", "arabic": "أَجَلْ، إِنَّهُ ظَرْفٌ مُلِئَ عِلْمًا وَفِقْهًا يَا صُهَيْبُ", "segs": null, "full_uz": "Ha, u ilm va fiqh bilan to'lgan bir inson, Suhayb.", "note": null},
  {"num": 270, "time": "00:19:22,259 --> 00:19:27,859", "arabic": "لَيْتَكَ تُرَافِقُنِي ذَاتَ مَرَّةٍ وَتَرَى بِعَيْنِكَ وَتَسْمَعَ بِأُذُنِكَ مَا أَقُولُهُ لَكَ", "segs": null, "full_uz": "Koshki bir marta men bilan borsang, aytganlarimni o'z ko'zing bilan ko'rib, qulog'ing bilan eshitsang.", "note": null},
  {"num": 271, "time": "00:19:27,859 --> 00:19:46,000", "arabic": "كَأَنِّي بِكَ يَا صَدِيقِي تُقْنِعُنِي بِالِانْضِمَامِ إِلَى الْمُعْتَزِلَةِ؟", "segs": null, "full_uz": "Do'stim, xuddi meni mu'taziliylarga qo'shilishga ko'ndirmoqchidek ko'rinasan?", "note": null},
  {"num": 272, "time": "00:19:46,000 --> 00:19:50,939", "arabic": "وَهَلْ أَنْتَ فَتًى غِرٌّ حَتَّى أُقْنِعَكَ بِمَا لَا تُحِبُّ؟", "segs": null, "full_uz": "Sen yosh va tajribasiz yigitmisan, yoqmagan narsaga seni ko'ndirsam?", "note": null},
  {"num": 273, "time": "00:19:50,939 --> 00:19:54,099", "arabic": "إِنَّمَا أَرَدْتُ مِنْكَ أَنْ تَرَى بِنَفْسِكَ وَتَحْكُمَ بِعَقْلِكَ", "segs": null, "full_uz": "Men faqat sening o'zing ko'rib, o'z aqling bilan hukm chiqarishingni xohladim.", "note": null},
  {"num": 274, "time": "00:19:54,099 --> 00:19:57,379", "arabic": "فَعَقْلُ الْإِنْسَانِ أَدَاتُهُ لِلْحُكْمِ وَالْقَرَارِ", "segs": null, "full_uz": "Chunki inson aqli — hukm va qaror chiqarish quroli.", "note": null},
  {"num": 275, "time": "00:19:57,380 --> 00:20:00,820", "arabic": "أَوَلَيْسَتِ الْحِكْمَةُ ضَالَّةَ الْمُؤْمِنِ؟", "segs": null, "full_uz": "Hikmat mo'minning yo'qotgan narsasi emasmi?", "note": "«الْحِكْمَةُ ضَالَّةُ الْمُؤْمِنِ» — mo'min hikmatni qayerda topsa oladi, degan mashhur ibora."},
  {"num": 276, "time": "00:20:00,820 --> 00:20:07,260", "arabic": "نَعَمِ الْحِكْمَةُ ضَالَّةُ الْمُؤْمِنِ وَالدِّينُ النَّصِيحَةُ", "segs": null, "full_uz": "Ha, hikmat mo'minning yo'qotgan narsasi va din — nasihatdir.", "note": null},
  {"num": 277, "time": "00:20:07,260 --> 00:20:10,780", "arabic": "وَأَنَا أَنْصَحُكَ يَا بَدْرُ أَنْ تَبْتَعِدَ عَنْ هَؤُلَاءِ الْقَوْمِ", "segs": null, "full_uz": "Men senga bu qavmdan uzoqlashishni nasihat qilaman, Badr.", "note": null},
  {"num": 278, "time": "00:20:10,780 --> 00:20:13,520", "arabic": "فَهُمْ خُصُومُ أَمِيرِ الْمُؤْمِنِينَ الرَّشِيدِ", "segs": null, "full_uz": "Chunki ular mo'minlar amiri Rashidning dushmanlari.", "note": null},
  {"num": 279, "time": "00:20:13,520 --> 00:20:17,320", "arabic": "غَفَرَ اللَّهُ لَكَ يَا صَاحِبِي غَفَرَ اللَّهُ لَكَ", "segs": null, "full_uz": "Alloh senga mag'firat qilsin, do'stim, Alloh senga mag'firat qilsin.", "note": null},
  {"num": 280, "time": "00:20:17,320 --> 00:20:22,320", "arabic": "مُنْذُ مَتَى كَانَ رِضَا أَمِيرِ الْمُؤْمِنِينَ مِقْيَاسًا لِلتَّمْيِيزِ بَيْنَ الْحَقِّ وَالْبَاطِلِ؟", "segs": null, "full_uz": "Mo'minlar amirining roziligi qachondan beri haq va botilni ajratish mezoni bo'ldi?", "note": null},
  {"num": 281, "time": "00:20:22,320 --> 00:20:24,960", "arabic": "إِنَّ مِقْيَاسَ تَمْيِيزِ الْحَقِّ وَالْبَاطِلِ هُوَ هُنَا", "segs": null, "full_uz": "Haq va botilni ajratish mezoni — mana shu yerda.", "note": null},
  {"num": 282, "time": "00:20:24,960 --> 00:20:35,220", "arabic": "اِسْمَعْنِي يَا بَدْرُ إِنَّ مِقْيَاسَ التَّمْيِيزِ بَيْنَ الْحَقِّ وَالْبَاطِلِ هُوَ كِتَابُ اللَّهِ وَسُنَّةُ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Meni eshit, Badr, haq va botilni ajratish mezoni — Allohning kitobi va Uning rasuli sunnatidir.", "note": null},
  {"num": 283, "time": "00:20:35,220 --> 00:20:37,640", "arabic": "وَلَيْسَ عَقْلَكَ الْمَرِيضَ", "segs": null, "full_uz": "Sening kasal aqling emas.", "note": null},
  {"num": 284, "time": "00:20:37,640 --> 00:20:46,340", "arabic": "وَكَيْفَ السَّبِيلُ إِلَى فَهْمِ كِتَابِ اللَّهِ وَسُنَّةِ رَسُولِهِ إِنْ لَمْ نُعْمِلْ فِيهِ عُقُولَنَا؟", "segs": null, "full_uz": "Agar unda aqlimizni ishlatmasak, Allohning kitobi va Uning rasuli sunnatini tushunishning yo'li qanday bo'ladi?", "note": null},
  {"num": 285, "time": "00:20:46,340 --> 00:20:49,380", "arabic": "إِنَّ الْعَقْلَ يَا صَدِيقِي هُوَ الْجِسْرُ بَيْنَ اللَّفْظِ وَمَعْنَاهُ", "segs": null, "full_uz": "Aql, do'stim, so'z bilan uning ma'nosi orasidagi ko'prikdir.", "note": null},
  {"num": 286, "time": "00:20:49,380 --> 00:20:51,120", "arabic": "بَيْنَ الْقَوْلِ وَالْعَمَلِ", "segs": null, "full_uz": "So'z va amal orasida.", "note": null},
  {"num": 287, "time": "00:20:51,120 --> 00:20:54,380", "arabic": "أَلَيْسَ ذَلِكَ مِنَ الْبَدِيهِيَّاتِ أَيْضًا؟", "segs": null, "full_uz": "Bu ham o'z-o'zidan ravshan narsalardan emasmi?", "note": null},
  {"num": 288, "time": "00:20:54,960 --> 00:21:00,460", "arabic": "إِنَّ شَيْخِي بِشْرًا وَمَنْ مَعَهُ يَضَعُونَ الْعَقْلَ فِي الْمَكَانِ الَّذِي وَضَعَهُ اللَّهُ لَهُ", "segs": null, "full_uz": "Ustozim Bishr va uning safdoshlari aqlni Alloh unga belgilagan o'rniga qo'yishadi.", "note": null},
  {"num": 289, "time": "00:21:00,460 --> 00:21:04,579", "arabic": "فَلَا تَحْكُمْ لِمُجَرَّدِ سَمَاعِكَ بِأُذُنِكَ يَا صُهَيْبُ", "segs": null, "full_uz": "Faqat qulog'ing bilan eshitganing uchungina hukm chiqarma, Suhayb.", "note": null},
  {"num": 290, "time": "00:21:21,400 --> 00:21:23,279", "arabic": "اَلسَّلَامُ عَلَيْكَ يَا أَخِي الْعَرَبِيَّ", "segs": null, "full_uz": "Senga salom bo'lsin, arab birodarim.", "note": null},
  {"num": 291, "time": "00:21:23,279 --> 00:21:26,359", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 292, "time": "00:21:26,359 --> 00:21:29,839", "arabic": "سَمِعْتُكَ قَبْلَ قَلِيلٍ تُحَدِّثُ النَّاسَ فِي الْمَجْلِسِ", "segs": null, "full_uz": "Sizni bir oz oldin majlisda odamlarga gapirayotganingizni eshitdim.", "note": null},
  {"num": 293, "time": "00:21:29,839 --> 00:21:32,319", "arabic": "وَقَدْ أَعْجَبَنِي مَا تَقُولُهُ", "segs": null, "full_uz": "Aytganlaringiz menga yoqdi.", "note": null},
  {"num": 294, "time": "00:21:32,319 --> 00:21:34,559", "arabic": "جَزَاكَ اللَّهُ كُلَّ خَيْرٍ", "segs": null, "full_uz": "Alloh senga barcha yaxshiliklar bilan mukofot bersin.", "note": null},
  {"num": 295, "time": "00:21:34,559 --> 00:21:38,639", "arabic": "أَحْسَبُ إِذَنْ أَنَّكَ فَقِيهٌ أَوْ شَيْخُ حَدِيثٍ", "segs": null, "full_uz": "Demak, siz faqih yoki hadis ustozisiz, deb o'ylayman.", "note": null},
  {"num": 296, "time": "00:21:38,639 --> 00:21:43,359", "arabic": "أَكْرَمَنِي اللَّهُ بِالتَّتَلْمُذِ عَلَى يَدِ الْقَاضِي أَبِي يُوسُفَ رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "Alloh meni qozi Abu Yusuf — Alloh unga rahmat qilsin — qo'lida shogird bo'lish sharafi bilan mukarram qildi.", "note": null},
  {"num": 297, "time": "00:21:43,359 --> 00:21:47,359", "arabic": "إِمَامِ أَهْلِ الْعِرَاقِ", "segs": null, "full_uz": "Iroq ahlining imomi.", "note": null},
  {"num": 298, "time": "00:21:47,359 --> 00:21:49,899", "arabic": "يَا مَرْحَبًا بِكَ يَا أَخِي", "segs": null, "full_uz": "Xush kelibsiz, birodarim.", "note": null},
  {"num": 299, "time": "00:21:49,899 --> 00:21:51,599", "arabic": "أَحْسَبُ أَنَّكَ لَسْتَ مِنْ بَغْدَادَ", "segs": null, "full_uz": "Menimcha, siz Bag'dodlik emassiz.", "note": null},
  {"num": 300, "time": "00:21:51,599 --> 00:21:58,740", "arabic": "هُوَ كَمَا تَقُولُ أَنَا مِنْ مَكَّةَ الْمُكَرَّمَةِ وَأُدْعَى مُحَمَّدَ بْنَ إِدْرِيسَ الشَّافِعِيَّ", "segs": null, "full_uz": "Aytganingizdek, men mukarram Makkadanman va Muhammad ibn Idris ash-Shofi'iy deb atalaman.", "note": null},
  {"num": 301, "time": "00:21:58,740 --> 00:22:02,259", "arabic": "وَأَنَا بِشْرٌ بِشْرٌ الْمَرِيسِيُّ", "segs": null, "full_uz": "Men esa Bishr, Bishr al-Marisiyman.", "note": null},
  {"num": 302, "time": "00:22:02,259 --> 00:22:04,639", "arabic": "أَهْلًا وَسَهْلًا بِكَ يَا أَخِي", "segs": null, "full_uz": "Xush kelibsiz, birodarim.", "note": null},
  {"num": 303, "time": "00:22:04,639 --> 00:22:08,240", "arabic": "حَسَنًا فَلْنَذْهَبْ إِلَى بَيْتِي لِنُكْمِلَ حَدِيثَنَا", "segs": null, "full_uz": "Xo'p, uyimga boraylik, suhbatimizni davom ettiraylik.", "note": null},
  {"num": 304, "time": "00:22:08,240 --> 00:22:10,219", "arabic": "أَخْشَى أَنَّنِي أُثَقِّلُ عَلَيْكَ", "segs": null, "full_uz": "Sizga og'irlik qilishimdan qo'rqaman.", "note": null},
  {"num": 305, "time": "00:22:10,219 --> 00:22:12,179", "arabic": "تَفَضَّلْ يَا أَخِي تَفَضَّلْ", "segs": null, "full_uz": "Marhamat, birodarim, marhamat.", "note": null},
  {"num": 306, "time": "00:22:12,179 --> 00:22:12,719", "arabic": "تَفَضَّلْ", "segs": null, "full_uz": "Marhamat.", "note": null},
  {"num": 307, "time": "00:22:12,719 --> 00:22:19,459", "arabic": "لَا أَحَبَّ إِلَى نَفْسِ الشَّافِعِيِّ مِنْ مُجَالَسَةِ الْفُقَهَاءِ وَطَلَبَةِ الْعِلْمِ", "segs": null, "full_uz": "Shofi'iy uchun fuqaho va ilm talabalari suhbatidan sevimliroq narsa yo'q.", "note": null},
  {"num": 308, "time": "00:22:19,460 --> 00:22:24,700", "arabic": "فَكَيْفَ بِمَنْ هُوَ تِلْمِيذٌ لِأَبِي يُوسُفَ رَحِمَهُمَا اللَّهُ", "segs": null, "full_uz": "Abu Yusufning shogirdi bo'lgan kishi bilan bo'lsa-chi — Alloh ikkisiga ham rahmat qilsin.", "note": null},
  {"num": 309, "time": "00:22:24,700 --> 00:22:27,940", "arabic": "شُكْرًا لَكَ هَذَا كَرَمٌ مِنْكَ", "segs": null, "full_uz": "Rahmat sizga, bu sizning saxovatingiz.", "note": null},
  {"num": 310, "time": "00:22:33,400 --> 00:22:36,779", "arabic": "اُعْذُرْنِي عَلَى هَذِهِ الزِّيَارَةِ الْمُفَاجِئَةِ يَا ابْنَ أَبِي دُؤَادٍ", "segs": null, "full_uz": "Bu to'satdan tashrif uchun meni kechiring, Ibn Abi Duod.", "note": null},
  {"num": 311, "time": "00:22:36,779 --> 00:22:40,559", "arabic": "فَصَدِيقِي بَدْرٌ أَصَرَّ عَلَى زِيَارَتِكَ وَالتَّعَرُّفِ عَلَيْكَ", "segs": null, "full_uz": "Do'stim Badr sizga tashrif buyurish va siz bilan tanishishga qat'iy turib oldi.", "note": null},
  {"num": 312, "time": "00:22:40,559 --> 00:22:44,340", "arabic": "شَرَفٌ كَبِيرٌ لِي أَنْ أَحْظَى بِشَرَفِ زِيَارَتِكَ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Sizning tashrifingiz sharafiga erishishim men uchun katta sharaf, Abu Abdulloh.", "note": null},
  {"num": 313, "time": "00:22:44,340 --> 00:22:49,340", "arabic": "بَدْرٌ هُوَ مَنْ حَدَّثْتُكَ عَنْهُ سَابِقًا", "segs": null, "full_uz": "Badr — bu ilgari sizga aytgan kishim.", "note": null},
  {"num": 314, "time": "00:22:49,339 --> 00:22:52,539", "arabic": "اَلَّذِي أَشْكَلَ عَلَيْهِ قَوْلُ اللَّهِ سُبْحَانَهُ وَتَعَالَى", "segs": null, "full_uz": "Ya'ni Alloh subhanahu va taoloning so'zi unga tushunarsiz bo'lgan kishi.", "note": null},
  {"num": 315, "time": "00:22:52,539 --> 00:22:56,220", "arabic": "وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ", "segs": null, "full_uz": "O'sha kuni yuzlar nurli bo'lib, Robbisiga qarab turadi.", "note": null},
  {"num": 316, "time": "00:22:56,220 --> 00:22:57,619", "arabic": "حَقًّا؟", "segs": null, "full_uz": "Rostanmi?", "note": null},
  {"num": 317, "time": "00:22:57,619 --> 00:23:01,839", "arabic": "لَا بُدَّ إِذَنْ أَنَّ بَدْرًا طَالِبٌ مُهْتَمٌّ بِدَرْسِهِ", "segs": null, "full_uz": "Demak, Badr darsiga qiziqadigan talaba bo'lishi kerak.", "note": null},
  {"num": 318, "time": "00:23:01,839 --> 00:23:03,079", "arabic": "مُهْتَمٌّ وَلَا شَكَّ", "segs": null, "full_uz": "Shubhasiz, qiziqadi.", "note": null},
  {"num": 319, "time": "00:23:03,079 --> 00:23:05,959", "arabic": "وَلَكِنْ فِي ذَلِكَ الْيَوْمِ جَانَبَهُ الصَّوَابُ", "segs": null, "full_uz": "Lekin o'sha kuni to'g'rilikdan chetlashib qoldi.", "note": null},
  {"num": 320, "time": "00:23:05,959 --> 00:23:08,599", "arabic": "مَنْ يَدْرِي يَا مُحَمَّدُ", "segs": null, "full_uz": "Kim biladi, Muhammad.", "note": null},
  {"num": 321, "time": "00:23:08,599 --> 00:23:12,899", "arabic": "رُبَّمَا نَكْتَشِفُ بَعْدَ فَتْرَةٍ أَنَّ الْحَقَّ مَعَهُ", "segs": null, "full_uz": "Balki bir muddatdan keyin haq unda ekanini bilib qolarmiz.", "note": null},
  {"num": 322, "time": "00:23:12,899 --> 00:23:14,619", "arabic": "وَنَحْنُ مِنْ جَانِبِنَا الصَّوَابُ", "segs": null, "full_uz": "Biz esa haqlik tomonidamiz.", "note": null},
  {"num": 323, "time": "00:23:14,619 --> 00:23:21,799", "arabic": "لِمَاذَا؟ أَمَا زَالَ لَدَيْكَ شَكٌّ بِمَا قُلْتُ؟", "segs": null, "full_uz": "Nega? Aytganlarimga hali ham shubhang bormi?", "note": null},
  {"num": 324, "time": "00:23:21,799 --> 00:23:26,299", "arabic": "لَا لَا لَا أَقْصِدُ ذَلِكَ يَا ابْنَ نُوحٍ لَقَدْ كَانَ كَلَامُكَ مُقْنِعًا", "segs": null, "full_uz": "Yo'q, yo'q, buni nazarda tutmadim, Ibn Nuh, gaping ishonarli edi.", "note": null},
  {"num": 325, "time": "00:23:26,299 --> 00:23:32,500", "arabic": "أَهْلًا بِأَخِي بَدْرٍ أَسْعَدَتْنِي زِيَارَتُكَ وَأَرْجُو أَنْ لَا تَكُونَ الْأَخِيرَةَ", "segs": null, "full_uz": "Aka Badrga xush kelibsiz, tashrifingiz meni xursand qildi, umid qilamanki, oxirgisi bo'lmas.", "note": null},
  {"num": 326, "time": "00:23:32,500 --> 00:23:35,199", "arabic": "أَنَا الَّذِي أَرْجُو ذَلِكَ، بَارَكَ اللَّهُ فِيكَ", "segs": null, "full_uz": "Buni istagan aynan menman, Alloh senga barakot bersin.", "note": null},
  {"num": 330, "time": "00:24:13,619 --> 00:24:22,659", "arabic": "حَارِثُ، الْحَقْ بِهَذِهِ الْمَرْأَةِ وَاعْرِفْ كُلَّ شَيْءٍ عَنْهَا أَحْوَالَهَا وَمَكَانَ إِقَامَتِهَا وَعُدْ إِلَيَّ عَلَى الْفَوْرِ", "segs": [{"ar": "حَارِثُ، الْحَقْ بِهَذِهِ الْمَرْأَةِ", "uz": "Horis, bu ayolning izidan bor"}, {"ar": "وَاعْرِفْ كُلَّ شَيْءٍ عَنْهَا أَحْوَالَهَا وَمَكَانَ إِقَامَتِهَا", "uz": "u haqida hamma narsani — ahvoli, turar joyini — bilib ol"}, {"ar": "وَعُدْ إِلَيَّ عَلَى الْفَوْرِ", "uz": "va darhol menga qayt"}], "full_uz": "Horis, bu ayolning izidan bor va u haqida hamma narsani — ahvoli, turar joyini — bilib, darhol menga qayt.", "note": null},
  {"num": 331, "time": "00:24:22,659 --> 00:24:27,079", "arabic": "وَكَيْفَ أَتْرُكُكَ وَحْدَكَ يَا مَوْلَايَ أَخَافُ أَنْ يُصِيبَكَ مَكْرُوهٌ لَا سَمَحَ اللَّهُ", "segs": null, "full_uz": "Sizni yolg'iz qanday tashlab keta olaman, xo'jayinim? Alloh saqlasin, sizga yomonlik yetishidan qo'rqaman.", "note": null},
  {"num": 332, "time": "00:24:27,079 --> 00:24:30,019", "arabic": "لَا تَخْشَ شَيْئًا يَا حَارِثُ لَا تَخْشَ عَلَيَّ", "segs": null, "full_uz": "Hech narsadan qo'rqma, Horis, men uchun qo'rqma.", "note": null},
  {"num": 333, "time": "00:24:30,019 --> 00:24:31,859", "arabic": "هَيَّا وَنَفِّذْ مَا قُلْتُ لَكَ", "segs": null, "full_uz": "Yur va senga aytganimni bajar.", "note": null},
  {"num": 336, "time": "00:24:33,220 --> 00:24:44,200", "arabic": "اَلْعَدَالَةُ الْمُطْلَقَةُ أَمْرٌ مُسْتَحِيلٌ", "segs": null, "full_uz": "Mutlaq adolat — imkonsiz narsa.", "note": null},
  {"num": 337, "time": "00:24:44,200 --> 00:24:51,019", "arabic": "أَيُّ ذَنْبٍ تَحْمِلُهُ فِي رَقَبَتِكَ يَا هَارُونُ دُونَ أَنْ تَدْرِيَ", "segs": null, "full_uz": "Bilmagan holingda, bo'yningda qanday gunoh ko'tarib yuribsan, Horun.", "note": null},
  {"num": 338, "time": "00:24:51,019 --> 00:24:53,019", "arabic": "أَيُّ ذَنْبٍ", "segs": null, "full_uz": "Qanday gunoh.", "note": null},
  {"num": 339, "time": "00:24:53,019 --> 00:24:59,160", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ", "segs": null, "full_uz": "Kuch-quvvat faqat Ulug' va Oliy Alloh bilandir.", "note": null},
  {"num": 340, "time": "00:24:59,160 --> 00:25:07,880", "arabic": "بِشْرٌ الْمَرِيسِيُّ", "segs": null, "full_uz": "Bishr al-Marisiy.", "note": null},
  {"num": 341, "time": "00:25:07,880 --> 00:25:10,880", "arabic": "أَجَلْ هَذَا هُوَ اسْمُ الرَّجُلِ", "segs": null, "full_uz": "Ha, bu kishining ismi shu.", "note": null},
  {"num": 342, "time": "00:25:10,880 --> 00:25:14,240", "arabic": "وَقَدْ قَالَ لِي إِنَّهُ مِنْ تَلَامِذَةِ أَبِي يُوسُفَ رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "U menga Abu Yusuf — Alloh unga rahmat qilsin — ning shogirdlaridan ekanini aytdi.", "note": null},
  {"num": 343, "time": "00:25:14,240 --> 00:25:16,779", "arabic": "رَحِمَ اللَّهُ أَبَا يُوسُفَ", "segs": null, "full_uz": "Alloh Abu Yusufga rahmat qilsin.", "note": null},
  {"num": 344, "time": "00:25:16,779 --> 00:25:19,279", "arabic": "أَجَلْ فَإِنَّ الرَّجُلَ لَمْ يَكْذِبْكَ", "segs": null, "full_uz": "Ha, u kishi senga yolg'on gapirmagan.", "note": null},
  {"num": 345, "time": "00:25:19,279 --> 00:25:21,279", "arabic": "هُوَ فِعْلًا مِنْ تَلَامِيذِهِ", "segs": null, "full_uz": "U haqiqatan ham uning shogirdlaridan.", "note": null},
  {"num": 346, "time": "00:25:21,279 --> 00:25:26,120", "arabic": "لَيْتَ الْمَرِيسِيَّ بَقِيَ عَلَى مَا تَعَلَّمَهُ مِنْ شَيْخِهِ", "segs": null, "full_uz": "Koshki Marisiy ustozidan o'rgangan narsasida qolganida.", "note": null},
  {"num": 347, "time": "00:25:26,120 --> 00:25:28,779", "arabic": "لِمَاذَا تَقُولُ ذَلِكَ؟", "segs": null, "full_uz": "Nega shunday deysiz?", "note": null},
  {"num": 348, "time": "00:25:29,160 --> 00:25:33,740", "arabic": "لِأَنَّ الْمَرِيسِيَّ هَذَا تَأَثَّرَ بِمُعْتَقَدِ أَهْلِ الِاعْتِزَالِ يَا شَافِعِيُّ", "segs": null, "full_uz": "Chunki bu Marisiy mu'tazila ahlining e'tiqodidan ta'sirlangan, ey Shofi'iy.", "note": null},
  {"num": 349, "time": "00:25:33,740 --> 00:25:37,240", "arabic": "أَتْبَعَهُ الشَّيْطَانُ فَكَانَ مِنَ الْغَاوِينَ", "segs": null, "full_uz": "Shayton unga ergashib, u yo'ldan ozganlardan bo'lib qoldi.", "note": null},
  {"num": 350, "time": "00:25:37,240 --> 00:25:40,220", "arabic": "فَلَعِبَ بِعَقْلِهِ بَعْضُ شُيُوخِ الْمُعْتَزِلَةِ", "segs": null, "full_uz": "Mu'tazila ustozlaridan ba'zilari uning aqli bilan o'ynashdi.", "note": null},
  {"num": 351, "time": "00:25:40,220 --> 00:25:45,400", "arabic": "فَجَيَّرَ كُلَّ مَا تَعَلَّمَهُ مِنْ فِقْهٍ هَائِلٍ لِنُصْرَةِ عَقِيدَتِهِ الْفَاسِدَةِ", "segs": null, "full_uz": "O'rgangan ulkan fiqh bilimini o'zining buzuq e'tiqodini himoya qilishga safarbar qildi.", "note": null},
  {"num": 352, "time": "00:25:45,400 --> 00:25:49,680", "arabic": "وَهُوَ الْيَوْمَ يَدْعُو إِلَى الْقَوْلِ بِخَلْقِ الْقُرْآنِ", "segs": null, "full_uz": "U bugun Qur'onning yaratilgan ekanligi haqidagi fikrga chaqirmoqda.", "note": null},
  {"num": 353, "time": "00:25:49,680 --> 00:25:53,560", "arabic": "أَعُوذُ بِاللَّهِ مِنْ أَنْ نَكُونَ مِمَّنْ آتَاهُ اللَّهُ آيَاتِهِ", "segs": null, "full_uz": "Alloh O'z oyatlarini bergan kishilardan bo'lib qolishimizdan Allohga sig'inaman.", "note": null},
  {"num": 354, "time": "00:25:53,560 --> 00:25:56,680", "arabic": "فَانْسَلَخَ مِنْهَا فَأَصْبَحَ مِنَ الْغَاوِينَ", "segs": null, "full_uz": "So'ngra undan chiqib, adashganlardan bo'lib qolgan.", "note": "Qur'ondagi (A'rof, 175-oyat) ma'nosiga ishora."},
  {"num": 355, "time": "00:25:56,680 --> 00:26:00,160", "arabic": "غَرِيبٌ أَمْرُ هَذَا الرَّجُلِ", "segs": null, "full_uz": "Bu kishining ishi g'alati.", "note": null},
  {"num": 356, "time": "00:26:00,160 --> 00:26:04,100", "arabic": "لَقَدْ بَدَا لِي فِي عَيْنِي فَقِيهًا", "segs": null, "full_uz": "Menga u ko'zimda faqih bo'lib ko'rindi.", "note": null},
  {"num": 357, "time": "00:26:04,100 --> 00:26:06,759", "arabic": "إِنَّهُ كَذَلِكَ لِلْأَسَفِ", "segs": null, "full_uz": "Afsuski, shunday.", "note": null},
  {"num": 358, "time": "00:26:06,759 --> 00:26:08,200", "arabic": "وَلَكِنْ مَا الْفَائِدَةُ", "segs": null, "full_uz": "Lekin uning nima foydasi bor?", "note": null},
  {"num": 359, "time": "00:26:08,200 --> 00:26:10,220", "arabic": "إِنْ لَمْ يَحْجُزْهُ فِقْهٌ", "segs": null, "full_uz": "Agar fiqh uni to'smasa.", "note": null},
  {"num": 360, "time": "00:26:10,220 --> 00:26:12,680", "arabic": "عَنِ الْوُقُوعِ فِي حَبَائِلِ الْمُبْتَدِعَةِ", "segs": null, "full_uz": "Bid'atchilar dom-dachasiga tushib qolishdan.", "note": null},
  {"num": 361, "time": "00:26:12,680 --> 00:26:14,299", "arabic": "وَشَرَكِ الضَّالِّينَ", "segs": null, "full_uz": "Va adashganlarning tuzog'idan.", "note": null},
  {"num": 362, "time": "00:26:14,299 --> 00:26:17,759", "arabic": "لَمْ يُجَاهِرْ بِذَلِكَ", "segs": null, "full_uz": "Buni oshkora aytmagan.", "note": null},
  {"num": 363, "time": "00:26:17,759 --> 00:26:21,960", "arabic": "لَقَدْ بَدَا لِي عَلَى غَيْرِ مَا تَقُولُ تَمَامًا", "segs": null, "full_uz": "Menga u siz aytgandan butunlay boshqacha ko'rindi.", "note": null},
  {"num": 364, "time": "00:26:21,960 --> 00:26:23,560", "arabic": "هَذَا الصِّنْفُ مِنَ النَّاسِ", "segs": null, "full_uz": "Bu turdagi odamlar.", "note": null},
  {"num": 365, "time": "00:26:23,560 --> 00:26:25,960", "arabic": "يُخَادِعُونَ اللَّهَ وَالَّذِينَ آمَنُوا", "segs": null, "full_uz": "Alloh va iymon keltirganlarni aldamoqchi bo'ladilar.", "note": "Qur'ondagi (Baqara, 9-oyat) ma'nosiga ishora."},
  {"num": 366, "time": "00:26:26,680 --> 00:26:29,920", "arabic": "لَكِنَّهُمْ فِي الْحَقِيقَةِ لَا يَخْدَعُونَ إِلَّا أَنْفُسَهُمْ", "segs": null, "full_uz": "Lekin haqiqatda faqat o'zlarini aldaydilar.", "note": null},
  {"num": 367, "time": "00:26:29,920 --> 00:26:34,519", "arabic": "وَقَدْ أَرَادَ بِذَلِكَ أَنْ يَقِفَ عَلَى حَقِيقَةِ اعْتِقَادِكَ", "segs": null, "full_uz": "U shu orqali sening haqiqiy e'tiqodingdan xabardor bo'lishni maqsad qilgan.", "note": null},
  {"num": 368, "time": "00:26:34,519 --> 00:26:38,880", "arabic": "وَظَنِّي أَنَّهُ يَوَدُّ أَنْ تَكُونَ مِنْ جَمَاعَتِهِ", "segs": null, "full_uz": "Fikrimcha, u sening o'z jamoasidan bo'lishingni xohlaydi.", "note": null},
  {"num": 369, "time": "00:26:38,880 --> 00:26:40,840", "arabic": "أَعُوذُ بِاللَّهِ", "segs": null, "full_uz": "Allohga sig'inaman.", "note": null},
  {"num": 370, "time": "00:26:40,840 --> 00:26:44,680", "arabic": "أَعُوذُ بِاللَّهِ مِنْ قَوْلِ أَهْلِ الْبَاطِلِ", "segs": null, "full_uz": "Botil ahlining so'zidan Allohga sig'inaman.", "note": null},
  {"num": 371, "time": "00:26:45,480 --> 00:26:49,680", "arabic": "وَقَانَا اللَّهُ شُرُورَ أَهْلِ الْبِدَعِ وَالْأَهْوَاءِ", "segs": null, "full_uz": "Alloh bizni bid'at va nafsoniy xohish ahlining yovuzligidan asrasin.", "note": null},
  {"num": 372, "time": "00:26:50,200 --> 00:26:53,460", "arabic": "جَنِّبْ أَمْثَالَهُ مَجْلِسَكَ يَا شَافِعِيُّ", "segs": null, "full_uz": "Shunga o'xshaganlarni majlisingdan yiroq tut, ey Shofi'iy.", "note": null},
  {"num": 373, "time": "00:26:53,460 --> 00:26:55,560", "arabic": "لَا يَا ابْنَ الْحَسَنِ لَا", "segs": null, "full_uz": "Yo'q, Ibn Hasan, yo'q.", "note": null},
  {"num": 374, "time": "00:26:56,680 --> 00:27:01,420", "arabic": "لَا، اَلنَّارُ الْمُشْتَعِلَةُ تَحْتَاجُ لِمَنْ يُطْفِئُهَا", "segs": null, "full_uz": "Yo'q, alangalangan olov uni o'chiradigan kishiga muhtoj.", "note": null},
  {"num": 375, "time": "00:27:01,420 --> 00:27:04,460", "arabic": "وَالضَّالُّ عَلَيْنَا أَنْ نُرْشِدَهُ", "segs": null, "full_uz": "Adashgan kishini esa to'g'ri yo'lga solishimiz kerak.", "note": null},
  {"num": 376, "time": "00:27:04,460 --> 00:27:10,519", "arabic": "وَمَا اسْتَفْعَلَ أَمْرُ هَؤُلَاءِ إِلَّا لِسُكُوتِنَا عَنْهُمْ وَتَجَنُّبِنَا لَهُمْ", "segs": null, "full_uz": "Bularning ishi faqat bizning ularga sukut saqlashimiz va ulardan qochishimiz tufayli kuchayib ketdi.", "note": null},
  {"num": 377, "time": "00:27:10,519 --> 00:27:12,500", "arabic": "يَا ابْنَ الْحَسَنِ", "segs": null, "full_uz": "Ey Ibn Hasan.", "note": null},
  {"num": 378, "time": "00:27:12,500 --> 00:27:18,799", "arabic": "اَلْجَاهِلُ يُعَلَّمُ وَالْغَافِلُ يُذَكَّرُ", "segs": null, "full_uz": "Bilmagan o'rgatiladi, g'ofil esa eslatiladi.", "note": null},
  {"num": 379, "time": "00:27:18,799 --> 00:27:23,779", "arabic": "إِنَّ مَنْ كَانَ عَلَى الْحَقِّ أَيُّهَا الْإِخْوَةُ", "segs": null, "full_uz": "Haq yo'lida bo'lgan kishi, ey birodarlar.", "note": null},
  {"num": 380, "time": "00:27:23,779 --> 00:27:28,220", "arabic": "لَا يَكْتَرِثُ لِمَنْ يَكِيدُونَ لَهُ حَتَّى لَوْ مَلَئُوا الْآفَاقَ", "segs": null, "full_uz": "Hatto ufqlarni to'ldirsalar ham, unga fitna qilayotganlarga parvo qilmaydi.", "note": null},
  {"num": 381, "time": "00:27:28,220 --> 00:27:31,299", "arabic": "فَالْمُؤْمِنُ قَوِيٌّ بِإِيمَانِهِ", "segs": null, "full_uz": "Mo'min o'z iymoni bilan kuchlidir.", "note": null},
  {"num": 382, "time": "00:27:31,299 --> 00:27:33,220", "arabic": "وَاثِقٌ بِرَبِّهِ", "segs": null, "full_uz": "Robbisiga ishongan holda.", "note": null},
  {"num": 383, "time": "00:27:33,220 --> 00:27:36,639", "arabic": "يَعْرِفُ بِأَنَّهُ سَيُمْتَحَنُ وَيُبْتَلَى", "segs": null, "full_uz": "U sinaladi va imtihon qilinadi, deb biladi.", "note": null},
  {"num": 384, "time": "00:27:36,639 --> 00:27:42,220", "arabic": "أَتَحْسَبُونَ أَنَّنَا أَوَّلُ مَنْ ظُلِمَ مِنْ أَجْلِ مَا يُؤْمِنُ بِهِ؟", "segs": null, "full_uz": "O'zi ishongan narsasi uchun zulm ko'rgan birinchi kishi biz deb o'ylaysizlarmi?", "note": null},
  {"num": 385, "time": "00:27:42,220 --> 00:27:43,099", "arabic": "لَا يَا إِخْوَتِي", "segs": null, "full_uz": "Yo'q, birodarlarim.", "note": null},
  {"num": 386, "time": "00:27:43,099 --> 00:27:45,740", "arabic": "لَسْنَا أَوَّلَ الْمَظْلُومِينَ", "segs": null, "full_uz": "Biz birinchi mazlumlar emasmiz.", "note": null},
  {"num": 387, "time": "00:27:45,740 --> 00:27:48,339", "arabic": "وَلَا هَارُونُ أَوَّلَ ظَالِمٍ", "segs": null, "full_uz": "Va Horun ham birinchi zolim emas.", "note": null},
  {"num": 388, "time": "00:27:48,339 --> 00:27:54,039", "arabic": "لَقَدْ سَبَقَنَا إِخْوَةٌ لَنَا ظُلِمُوا مِنْ أَجْلِ مَا يُؤْمِنُونَ بِهِ", "segs": null, "full_uz": "Bizdan oldin o'zlari ishongan narsa uchun zulm ko'rgan birodarlarimiz o'tgan.", "note": null},
  {"num": 389, "time": "00:27:54,039 --> 00:27:56,019", "arabic": "وَلَكِنَّهُمْ لَمْ يَهِنُوا", "segs": null, "full_uz": "Lekin ular zaiflashmadilar.", "note": null},
  {"num": 390, "time": "00:27:56,019 --> 00:27:57,459", "arabic": "لِمَاذَا؟", "segs": null, "full_uz": "Nega?", "note": null},
  {"num": 391, "time": "00:27:57,459 --> 00:28:02,339", "arabic": "لِأَنَّهُمْ أَسْلَمُوا قِيَادَهُمْ لِلَّهِ سُبْحَانَهُ وَتَعَالَى", "segs": null, "full_uz": "Chunki ular o'z jilovlarini Alloh subhanahu va taologa topshirgan edilar.", "note": null},
  {"num": 392, "time": "00:28:02,919 --> 00:28:04,559", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 393, "time": "00:28:04,559 --> 00:28:07,679", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 394, "time": "00:28:07,679 --> 00:28:08,339", "arabic": "تَفَضَّلُوا", "segs": null, "full_uz": "Marhamat.", "note": null},
  {"num": 395, "time": "00:28:08,980 --> 00:28:13,599", "arabic": "تَأَخَّرْتَ عَلَيْنَا أَيُّهَا الْمَرِيسِيُّ", "segs": null, "full_uz": "Kechikding, ey Marisiy.", "note": null},
  {"num": 396, "time": "00:28:13,599 --> 00:28:18,279", "arabic": "صَادَفْتُ الْيَوْمَ رَجُلًا لَمْ تَرَ عَيْنَايَ مِثْلَهُ", "segs": null, "full_uz": "Bugun ko'zim hech qachon ko'rmagan bir kishiga duch keldim.", "note": null},
  {"num": 397, "time": "00:28:18,279 --> 00:28:21,200", "arabic": "إِنَّهُ مِنْ مَكَّةَ الْمُكَرَّمَةِ", "segs": null, "full_uz": "U mukarram Makkadan.", "note": null},
  {"num": 398, "time": "00:28:21,200 --> 00:28:24,960", "arabic": "وَاسْمُهُ مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ", "segs": null, "full_uz": "Ismi Muhammad ibn Idris ash-Shofi'iy.", "note": null},
  {"num": 399, "time": "00:28:24,960 --> 00:28:27,819", "arabic": "قُرَشِيٌّ هَاشِمِيٌّ", "segs": null, "full_uz": "Qurayshiy, hoshimiy.", "note": null},
  {"num": 400, "time": "00:28:27,819 --> 00:28:33,460", "arabic": "إِذَنْ فَهُوَ ضَالٌّ كَابْنِ عَمِّهِ هَارُونَ", "segs": null, "full_uz": "Demak, u amakivachchasi Horunga o'xshab adashgan.", "note": null},
  {"num": 401, "time": "00:28:33,460 --> 00:28:34,759", "arabic": "لَا يَا ابْنَ الْأَشْرَسِ", "segs": null, "full_uz": "Yo'q, Ibn Ashras.", "note": null},
  {"num": 402, "time": "00:28:34,759 --> 00:28:40,779", "arabic": "إِنَّهُ فَقِيهٌ حَافِظٌ مُحَدِّثٌ مُتَكَلِّمٌ فَصِيحٌ شَاعِرٌ", "segs": null, "full_uz": "U faqih, hofiz, muhaddis, mutakallim, notiq va shoirdir.", "note": null},
  {"num": 403, "time": "00:28:40,779 --> 00:28:43,399", "arabic": "وَمَا الَّذِي جَمَعَكَ بِهِ يَا أَبَا عَبْدِ الرَّحْمَنِ؟", "segs": null, "full_uz": "Sizni u bilan nima birlashtirdi, Abu Abdurahmon?", "note": null},
  {"num": 404, "time": "00:28:43,399 --> 00:28:45,220", "arabic": "قَدَرُ اللَّهِ جَمَعَنَا", "segs": null, "full_uz": "Bizni Allohning taqdiri birlashtirdi.", "note": null},
  {"num": 405, "time": "00:28:45,220 --> 00:28:51,640", "arabic": "وَإِنِّي لَأَرْجُو مِنَ اللَّهِ أَنْ يَهْدِيَهُ إِلَى حَقِيقَةِ الْإِيمَانِ كَمَا هَدَانَا مِنْ قَبْلُ", "segs": null, "full_uz": "Allohdan uni ilgari bizni hidoyat qilganidek, iymonning haqiqatiga hidoyat qilishini so'rayman.", "note": null},
  {"num": 406, "time": "00:28:51,640 --> 00:28:54,339", "arabic": "فَهُوَ مَكْسَبٌ لَنَا وَأَيُّمَا مَكْسَبٍ", "segs": null, "full_uz": "U biz uchun yutuq, qanday katta yutuq!", "note": null},
  {"num": 407, "time": "00:28:54,339 --> 00:28:58,059", "arabic": "إِذَنْ فَأَنْتَ تُحَدِّثُ نَفْسَكَ بِضَمِّهِ إِلَيْنَا", "segs": null, "full_uz": "Demak, o'zingga uni bizga qo'shib olishni o'ylab yuribsan.", "note": null},
  {"num": 408, "time": "00:28:58,059 --> 00:29:03,220", "arabic": "لَوْ كَانَ الْأَمْرُ بِيَدِي لَفَعَلْتُهُ السَّاعَةَ إِنَّهُ فَوْقَ مَا أَصِفُ", "segs": null, "full_uz": "Agar ish o'z qo'limda bo'lsa, hoziroq shunday qilardim, u tasvirlay olganimdan ham a'lo.", "note": null},
  {"num": 409, "time": "00:29:03,880 --> 00:29:08,440", "arabic": "أَمْثَالُ هَؤُلَاءِ قَدْ رَانَ عَلَى قُلُوبِهِمْ بِمَا يَكْسِبُونَ", "segs": null, "full_uz": "Shu kabilarning qalbiga qilgan gunohlari tufayli pardalar tortilgan.", "note": "Qur'ondagi (Mutaffifin, 14-oyat) ma'nosiga ishora."},
  {"num": 410, "time": "00:29:08,440 --> 00:29:12,220", "arabic": "وَأَتْبَعُوا أَنْفُسَهُمْ هَوَاهَا فَلَا تَرْجُ مِنْهُمْ شَيْئًا", "segs": null, "full_uz": "O'zlari nafslarining xohishiga ergashishgan, ulardan hech narsa kutma.", "note": null},
  {"num": 411, "time": "00:29:12,220 --> 00:29:16,480", "arabic": "لَا بَأْسَ مِنَ الْمُحَاوَلَةِ يَا ابْنَ الْأَشْرَسِ لَا نَخْسَرُ شَيْئًا", "segs": null, "full_uz": "Urinishning zarari yo'q, Ibn Ashras, hech narsa yo'qotmaymiz.", "note": null},
  {"num": 412, "time": "00:29:16,480 --> 00:29:20,400", "arabic": "إِذَنْ نَتْرُكُ الْأَمْرَ لَكَ يَا أَبَا عَبْدِ الرَّحْمَنِ", "segs": null, "full_uz": "Demak, ishni sizga qoldiramiz, Abu Abdurahmon.", "note": null},
  {"num": 413, "time": "00:29:20,400 --> 00:29:23,680", "arabic": "فَأَنْتَ أَلْسَنُنَا وَأَفْقَهُنَا فِي دِينِ اللَّهِ", "segs": null, "full_uz": "Chunki siz bizning tilimiz va Alloh dinida eng fiqhlimizsiz.", "note": null},
  {"num": 414, "time": "00:29:23,680 --> 00:29:26,120", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا رَجُلُ", "segs": null, "full_uz": "Alloh senga barakot bersin, azizim.", "note": null},
  {"num": 415, "time": "00:29:42,220 --> 00:29:49,880", "arabic": "إِنْ أَرَدْتَ شِرَائِي", "segs": null, "full_uz": "Meni sotib olmoqchi bo'lsang.", "note": null},
  {"num": 416, "time": "00:29:49,880 --> 00:29:51,700", "arabic": "فَلِي شَرْطٌ", "segs": null, "full_uz": "Mening bir shartim bor.", "note": null},
  {"num": 417, "time": "00:29:51,700 --> 00:29:53,539", "arabic": "إِنْ قَبِلْتَ بِهِ", "segs": null, "full_uz": "Agar uni qabul qilsang.", "note": null},
  {"num": 418, "time": "00:29:53,539 --> 00:29:54,559", "arabic": "وُفِّقْتَ", "segs": null, "full_uz": "Muvaffaq bo'lasan.", "note": null},
  {"num": 419, "time": "00:29:54,559 --> 00:29:56,059", "arabic": "وَإِنْ لَمْ تَقْبَلْ", "segs": null, "full_uz": "Agar qabul qilmasang.", "note": null},
  {"num": 420, "time": "00:29:56,059 --> 00:29:57,700", "arabic": "فَأَنَا لَسْتُ لِلْبَيْعِ", "segs": null, "full_uz": "Men sotuvga emasman.", "note": null},
  {"num": 421, "time": "00:29:57,700 --> 00:30:00,100", "arabic": "وَمَنْ أَنْتِ حَتَّى تَشْتَرِطِي؟", "segs": null, "full_uz": "Sen shart qo'yishga kimsan?", "note": null},
  {"num": 422, "time": "00:30:00,100 --> 00:30:00,720", "arabic": "ثَكِلَتْكَ", "segs": null, "full_uz": "Onang seni yo'qotsin!", "note": "Xafagarchilik yoki g'azab ohangida aytiladigan qarg'ish ibora."},
  {"num": 423, "time": "00:30:00,720 --> 00:30:01,480", "arabic": "قُولِي شَرْطَكِ", "segs": null, "full_uz": "Shartingni ayt.", "note": null},
  {"num": 424, "time": "00:30:01,480 --> 00:30:03,700", "arabic": "إِنِّي أَسْمَعُكِ", "segs": null, "full_uz": "Men seni eshityapman.", "note": null},
  {"num": 425, "time": "00:30:03,700 --> 00:30:06,860", "arabic": "لَا أُرِيدُ أَنْ يَسْمَعَ شَرْطِي أَحَدٌ غَيْرُكَ", "segs": null, "full_uz": "Shartimni sendan boshqa hech kim eshitishini xohlamayman.", "note": null},
  {"num": 426, "time": "00:30:06,860 --> 00:30:11,000", "arabic": "إِنْ كُنْتِ لَا تُمَانِعِينَ يَا سَيِّدَتِي", "segs": null, "full_uz": "Agar qarshi bo'lmasangiz, xonim.", "note": null},
  {"num": 427, "time": "00:30:11,000 --> 00:30:14,099", "arabic": "أُرِيدُ أَنْ أَتَحَدَّثَ مَعَهَا وَحْدَنَا", "segs": null, "full_uz": "U bilan yolg'iz gaplashishni xohlayman.", "note": null},
  {"num": 428, "time": "00:30:14,099 --> 00:30:18,720", "arabic": "تَعَالَ مَعِي يَا حَنْظَلَةُ", "segs": null, "full_uz": "Men bilan kel, Hanzala.", "note": null},
  {"num": 430, "time": "00:30:26,779 --> 00:30:28,660", "arabic": "هَا قَدْ أَصْبَحْنَا وَحْدَنَا", "segs": null, "full_uz": "Mana, ikkimiz yolg'iz qoldik.", "note": null},
  {"num": 431, "time": "00:30:28,660 --> 00:30:30,319", "arabic": "تَكَلَّمِي", "segs": null, "full_uz": "Gapir.", "note": null},
  {"num": 432, "time": "00:30:30,319 --> 00:30:33,059", "arabic": "قَدْ عَلِمْتُ أَنَّ لَدَيْكَ أُخْتًا مَرِيضَةً", "segs": null, "full_uz": "Bilib oldimki, sizda kasal opa-singil bor.", "note": null},
  {"num": 433, "time": "00:30:33,059 --> 00:30:35,839", "arabic": "وَأَنَّكَ تُرِيدُنِي أَنْ أَقُومَ عَلَى خِدْمَتِهَا", "segs": null, "full_uz": "Va meni unga xizmat qilishimni istaysiz.", "note": null},
  {"num": 434, "time": "00:30:35,839 --> 00:30:36,839", "arabic": "وَأَنَا مُوَافِقَةٌ", "segs": null, "full_uz": "Men roziman.", "note": null},
  {"num": 435, "time": "00:30:36,839 --> 00:30:39,940", "arabic": "وَلَكِنِّي سَأَكُونُ فِي بَيْتِكَ خَادِمَةً", "segs": null, "full_uz": "Lekin men uyingizda xizmatkor bo'laman.", "note": null},
  {"num": 436, "time": "00:30:41,960 --> 00:30:46,100", "arabic": "خَادِمَةً فَقَطْ. أَنَا حُرَّةٌ", "segs": [{"ar": "خَادِمَةً فَقَطْ", "uz": "faqat xizmatkor"}, {"ar": "أَنَا حُرَّةٌ", "uz": "men ozodman"}], "full_uz": "Faqat xizmatkor. Men ozodman.", "note": null},
  {"num": 437, "time": "00:30:46,100 --> 00:30:48,340", "arabic": "وَلَكِنَّكَ لَنْ تُصَدِّقَنِي", "segs": null, "full_uz": "Lekin menga ishonmaysiz.", "note": null},
  {"num": 438, "time": "00:30:48,340 --> 00:30:50,519", "arabic": "وَلَا يَعْنِينِي أَنْ تُصَدِّقَنِي", "segs": null, "full_uz": "Menga ishonish-ishonmasligingiz farqi yo'q.", "note": null},
  {"num": 439, "time": "00:30:50,519 --> 00:30:52,740", "arabic": "فَكِّرْ فِي شَرْطِي", "segs": null, "full_uz": "Shartim haqida o'ylab ko'ring.", "note": null},
  {"num": 440, "time": "00:30:52,740 --> 00:30:55,519", "arabic": "وَلَا أَطْلُبُ مِنْكَ رَدًّا الْآنَ", "segs": null, "full_uz": "Va hozir sizdan javob talab qilmayman.", "note": null},
  {"num": 441, "time": "00:30:55,519 --> 00:30:58,660", "arabic": "إِنْ قَبِلْتَ فَعُدْ", "segs": null, "full_uz": "Agar qabul qilsangiz, qaytib keling.", "note": null},
  {"num": 442, "time": "00:30:58,660 --> 00:31:01,660", "arabic": "وَإِلَّا فَلَا تَعُدْ أَبَدًا", "segs": null, "full_uz": "Aks holda, aslo qaytmang.", "note": null},
  {"num": 443, "time": "00:31:09,940 --> 00:31:22,940", "arabic": "مَاذَا قَالَتْ لَكَ هَذِهِ الْمَجْنُونَةُ؟", "segs": null, "full_uz": "Bu jinni senga nima dedi?", "note": null},
  {"num": 444, "time": "00:31:24,180 --> 00:31:24,840", "arabic": "لَا شَيْءَ مُهِمٌّ", "segs": null, "full_uz": "Hech narsa muhim emas.", "note": null},
  {"num": 445, "time": "00:31:24,840 --> 00:31:27,880", "arabic": "قَدْ رَقَّتْ لِي وَأَظُنُّنِي سَأَشْتَرِيهَا", "segs": null, "full_uz": "U menga yumshadi, menimcha, uni sotib olaman.", "note": null},
  {"num": 446, "time": "00:31:27,880 --> 00:31:29,900", "arabic": "قَدْ تَأَخَّرْتُ الْآنَ", "segs": null, "full_uz": "Hozir kechikib qoldim.", "note": null},
  {"num": 447, "time": "00:31:29,900 --> 00:31:32,580", "arabic": "سَأَعُودُ قَرِيبًا لِنَتَّفِقَ عَلَى كُلِّ شَيْءٍ", "segs": null, "full_uz": "Hamma narsa haqida kelishish uchun tez orada qaytaman.", "note": null},
  {"num": 448, "time": "00:31:32,580 --> 00:31:35,180", "arabic": "عَلَى الرَّحْبِ وَالسَّعَةِ فِي أَيِّ وَقْتٍ تَشَاءُ", "segs": null, "full_uz": "Xohlagan vaqtingizda marhamat, xush kelibsiz.", "note": null},
  {"num": 449, "time": "00:31:39,940 --> 00:31:59,940", "arabic": "هَلْ يَسْتَحِقُّ هَارُونُ أَنْ يَجْلِسَ عَلَى كُرْسِيِّ الْخِلَافَةِ؟", "segs": null, "full_uz": "Horun xalifalik taxtida o'tirishga loyiqmi?", "note": null},
  {"num": 450, "time": "00:31:59,940 --> 00:32:05,120", "arabic": "إِنَّ مِنْ وَرَائِكَ النَّارَ وَمِنْ أَمَامِكَ الْجَنَّةَ", "segs": null, "full_uz": "Sening ortingda do'zax, oldingda esa jannat bor.", "note": null},
  {"num": 451, "time": "00:32:05,119 --> 00:32:10,439", "arabic": "وَوَاللَّهِ إِنِّي لَأَخْشَى أَنْ تَكُونَ الْأُولَى لِلثَّانِيَةِ", "segs": null, "full_uz": "Alloh haqqi, birinchisi ikkinchisiga to'siq bo'lishidan qo'rqaman.", "note": null},
  {"num": 452, "time": "00:32:10,439 --> 00:32:16,939", "arabic": "فَمَنِ اسْتُرْعِيَ رَعِيَّةً وَلَمْ يَحُطْهُمْ بِنَصِيحَةٍ", "segs": null, "full_uz": "Kimki fuqaroga mas'ul etib qo'yilib, ularni nasihat bilan o'rab olmasa.", "note": null},
  {"num": 453, "time": "00:32:16,939 --> 00:32:20,239", "arabic": "لَمْ يَجِدْ رِيحَ الْجَنَّةِ", "segs": null, "full_uz": "Jannat hidini sezmaydi.", "note": null},
  {"num": 454, "time": "00:32:20,239 --> 00:32:24,699", "arabic": "وَإِنَّ أَشَدَّ الْغِشِّ غِشُّ الْوَالِي لِرَعِيَّتِهِ", "segs": null, "full_uz": "Eng qattiq firibgarlik — hukmdorning o'z fuqarosiga qilgan firibgarligidir.", "note": null},
  {"num": 455, "time": "00:32:24,699 --> 00:32:29,779", "arabic": "اَللَّهُمَّ أَظِلَّنَا بِظِلِّكَ", "segs": null, "full_uz": "Ey Alloh, bizni O'z soyangda soyalantirgin.", "note": null},
  {"num": 456, "time": "00:32:29,779 --> 00:32:32,399", "arabic": "يَوْمَ لَا ظِلَّ إِلَّا ظِلُّكَ", "segs": null, "full_uz": "O'sha kunda Sening soyangdan boshqa soya yo'q.", "note": null},
  {"num": 457, "time": "00:32:32,400 --> 00:32:37,340", "arabic": "عُدْتَ يَا حَارِثُ", "segs": null, "full_uz": "Qaytding, Horis.", "note": null},
  {"num": 458, "time": "00:32:37,340 --> 00:32:41,840", "arabic": "اَلسَّلَامُ عَلَيْكَ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Sizga salom bo'lsin, ey mo'minlar amiri.", "note": null},
  {"num": 459, "time": "00:32:41,840 --> 00:32:44,960", "arabic": "عَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 460, "time": "00:32:44,960 --> 00:32:46,700", "arabic": "مَاذَا رَأَيْتَ؟", "segs": null, "full_uz": "Nima ko'rding?", "note": null},
  {"num": 461, "time": "00:32:46,700 --> 00:32:49,680", "arabic": "لَقَدْ لَحِقْتُ الْعَجُوزَةَ إِلَى أَنْ وَصَلَتْ دَارَهَا يَا مَوْلَايَ", "segs": null, "full_uz": "Kampirning izidan uyiga yetguncha bordim, xo'jayinim.", "note": null},
  {"num": 462, "time": "00:32:49,680 --> 00:32:51,940", "arabic": "وَدَارُهَا لَا يَدْخُلُهَا الْجُرَذُ", "segs": null, "full_uz": "Uyiga hatto sichqon ham kirmaydi.", "note": "Kinoya — juda kambag'al va harobaga aylangan uy ma'nosida."},
  {"num": 463, "time": "00:32:51,940 --> 00:32:53,720", "arabic": "إِنَّهَا فَقِيرَةٌ جِدًّا", "segs": null, "full_uz": "U juda kambag'al.", "note": null},
  {"num": 464, "time": "00:32:53,720 --> 00:32:57,360", "arabic": "وَأَخْبَرَنِي جِيرَانُهَا أَنْ لَا مُعِينَ لَهَا إِلَّا اللَّهُ", "segs": null, "full_uz": "Qo'shnilari uning Allohdan boshqa yordamchisi yo'qligini aytishdi.", "note": null},
  {"num": 465, "time": "00:32:57,360 --> 00:33:00,720", "arabic": "لَا إِلَهَ إِلَّا اللَّهُ", "segs": null, "full_uz": "Allohdan o'zga iloh yo'q.", "note": null},
  {"num": 466, "time": "00:33:00,720 --> 00:33:06,740", "arabic": "مِنْ صَبِيحَةِ الْغَدِ جِدْ لَهَا دَارًا تَلِيقُ بِهَا", "segs": null, "full_uz": "Ertaga tongdanoq unga munosib uy topib bering.", "note": null},
  {"num": 467, "time": "00:33:06,740 --> 00:33:11,360", "arabic": "وَأْمُرْ لَهَا بِنَفَقَةٍ شَهْرِيَّةٍ مِنْ بَيْتِ مَالِ الْمُسْلِمِينَ", "segs": null, "full_uz": "Va musulmonlar bayt ul-molidan unga oylik nafaqa tayinlang.", "note": null},
  {"num": 468, "time": "00:33:11,360 --> 00:33:17,259", "arabic": "وَلْتُخْبِرْنَا الْعُيُونُ عَمَّا فِي مِثْلِ حَالِهَا لِيَكُونَ لَهُمْ مِثْلُ مَا لَهَا", "segs": null, "full_uz": "Josuslarimiz uning holatidagi boshqalar haqida ham xabar bersin, ularga ham xuddi shunday berilsin.", "note": null},
  {"num": 469, "time": "00:33:17,259 --> 00:33:18,900", "arabic": "أَمْرُ مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinim buyurgan ish.", "note": null},
  {"num": 470, "time": "00:33:18,900 --> 00:33:24,120", "arabic": "يُنَفَّذُ مَا قُلْتُ مُنْذُ صَبِيحَةِ الْغَدِ هَلْ فَهِمْتَ؟", "segs": null, "full_uz": "Aytganim ertaga tongdan boshlab bajarilsin, tushundingmi?", "note": null},
  {"num": 471, "time": "00:33:24,120 --> 00:33:25,779", "arabic": "سَمْعًا وَطَاعَةً يَا مَوْلَايَ", "segs": null, "full_uz": "Eshitdik va bo'ysunamiz, xo'jayinim.", "note": null},
  {"num": 472, "time": "00:33:25,779 --> 00:33:35,180", "arabic": "قُلْنَا إِنَّ الْأَصْلَ الْأَوَّلَ فِي مَذْهَبِنَا أَيُّهَا الْقَوْمُ هُوَ التَّوْحِيدُ", "segs": null, "full_uz": "Aytdikki, ey qavm, mazhabimizning birinchi asosi — tavhiddir.", "note": null},
  {"num": 473, "time": "00:33:35,180 --> 00:33:41,319", "arabic": "وَنَعْنِي بِهِ إِثْبَاتَ وَحْدَانِيَّةِ اللَّهِ وَنَفْيَ الْمِثْلِ عَنْهُ", "segs": null, "full_uz": "Bundan biz Allohning yagonaligini isbotlash va Unga o'xshashlikni inkor qilishni nazarda tutamiz.", "note": null},
  {"num": 474, "time": "00:33:41,319 --> 00:33:43,359", "arabic": "وَالْأَصْلُ الثَّانِي هُوَ الْعَقْلُ", "segs": null, "full_uz": "Ikkinchi asos esa — aqldir.", "note": null},
  {"num": 475, "time": "00:33:43,359 --> 00:33:50,579", "arabic": "وَنَعْنِي بِهِ قِيَاسَ أَحْكَامِ اللَّهِ عَلَى مَا يَقْتَضِيهِ الْعَقْلُ وَالْحِكْمَةُ", "segs": null, "full_uz": "Bundan biz Allohning hukmlarini aql va hikmat talab qilgan narsaga qiyoslashni nazarda tutamiz.", "note": null},
  {"num": 476, "time": "00:33:50,579 --> 00:33:55,099", "arabic": "فَالْعَقْلُ مُسْتَقِلٌّ بِالتَّحْسِينِ وَالتَّقْبِيحِ", "segs": null, "full_uz": "Chunki aql yaxshi va yomonni belgilashda mustaqildir.", "note": null},
  {"num": 477, "time": "00:33:55,099 --> 00:33:58,959", "arabic": "فَمَا حَسَّنَهُ الْعَقْلُ كَانَ حَسَنًا", "segs": null, "full_uz": "Aql nimani yaxshi deb hisoblasa, u yaxshidir.", "note": null},
  {"num": 478, "time": "00:33:58,959 --> 00:34:02,099", "arabic": "وَمَا قَبَّحَهُ كَانَ قَبِيحًا", "segs": null, "full_uz": "Va nimani yomon deb hisoblasa, u yomondir.", "note": null},
  {"num": 479, "time": "00:34:02,759 --> 00:34:06,379", "arabic": "مَاذَا حَدَثَ مَعَ زَمِيلِكَ فِي حَلْقَةِ الدَّرْسِ؟", "segs": null, "full_uz": "Dars halqasidagi hamkasbing bilan nima bo'ldi?", "note": null},
  {"num": 480, "time": "00:34:06,379 --> 00:34:06,939", "arabic": "صُهَيْبٌ", "segs": null, "full_uz": "Suhayb.", "note": null},
  {"num": 481, "time": "00:34:06,939 --> 00:34:09,319", "arabic": "إِنَّهُ لَأَحْمَقُ لَيْسَ إِلَّا", "segs": null, "full_uz": "U shunchaki ahmoq, xolos.", "note": null},
  {"num": 482, "time": "00:34:09,319 --> 00:34:11,099", "arabic": "إِذَا فَشِلْتَ مَعَهُ", "segs": null, "full_uz": "Agar u bilan muvaffaqiyatsizlikka uchrasang.", "note": null},
  {"num": 483, "time": "00:34:11,759 --> 00:34:14,339", "arabic": "فَقَدْ ذَهَبَ كَلَامِي مَعَهُ سُدًى", "segs": null, "full_uz": "Demak, u bilan gapim behuda ketdi.", "note": null},
  {"num": 484, "time": "00:34:14,339 --> 00:34:16,519", "arabic": "إِنَّهُ لَا يَسْتَحِقُّ الْعَنَاءَ", "segs": null, "full_uz": "U azob chekishga arzimaydi.", "note": null},
  {"num": 485, "time": "00:34:16,519 --> 00:34:18,039", "arabic": "لَا طَائِلَ مِنْ وَرَائِهِ", "segs": null, "full_uz": "Undan hech qanday foyda yo'q.", "note": null},
  {"num": 486, "time": "00:34:18,039 --> 00:34:18,639", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 487, "time": "00:34:18,639 --> 00:34:20,460", "arabic": "لَا يَا بَدْرُ", "segs": null, "full_uz": "Yo'q, Badr.", "note": null},
  {"num": 488, "time": "00:34:20,460 --> 00:34:23,079", "arabic": "لَا أُحِبُّ أَنْ أَسْمَعَ مِثْلَ هَذَا الْكَلَامِ مِنْكَ", "segs": null, "full_uz": "Sendan bunday gaplarni eshitishni yoqtirmayman.", "note": null},
  {"num": 489, "time": "00:34:23,079 --> 00:34:25,059", "arabic": "عَلَيْكَ أَنْ لَا تَيْأَسَ مِنْ شَخْصٍ مَهْمَا كَانَ", "segs": null, "full_uz": "Kim bo'lishidan qat'i nazar, biror kishidan umidingni uzmasliging kerak.", "note": null},
  {"num": 490, "time": "00:34:25,059 --> 00:34:29,340", "arabic": "إِنْ بَقِينَا نَتَرَفَّعُ عَنِ النَّاسِ لَبَقِيَ أَكْثَرُهُمْ فِي الضَّلَالَةِ", "segs": null, "full_uz": "Agar odamlardan yuqori qarab yurishda davom etsak, ko'plari adashuvda qolib ketaveradi.", "note": null},
  {"num": 491, "time": "00:34:29,340 --> 00:34:32,460", "arabic": "إِنَّ الْأَمِيرَ عَبْدَ اللَّهِ الْمَأْمُونَ يَا مَوْلَايَ", "segs": null, "full_uz": "Amir Abdulloh Ma'mun, xo'jayinim.", "note": null},
  {"num": 492, "time": "00:34:32,460 --> 00:34:35,719", "arabic": "يَتَفَصَّدُ ذَكَاءً وَنَجَابَةً", "segs": null, "full_uz": "Aql-idrok va zukkolikdan tomchilab turibdi.", "note": null},
  {"num": 493, "time": "00:34:35,719 --> 00:34:39,380", "arabic": "وَلَا أَكُونُ مُبَالِغًا إِنْ قُلْتُ", "segs": null, "full_uz": "Agar shunday desam, mubolag'a qilgan bo'lmayman.", "note": null},
  {"num": 494, "time": "00:34:39,380 --> 00:34:42,900", "arabic": "إِنَّنِي لَمْ أَرَ شَابًّا فِي عُمْرِهِ", "segs": null, "full_uz": "Men uning yoshidagi bir yigitni ko'rmaganman.", "note": null},
  {"num": 495, "time": "00:34:42,900 --> 00:34:45,519", "arabic": "يُفَكِّرُ كَمَا يُفَكِّرُ الْمُكْتَهِلُونَ", "segs": null, "full_uz": "O'rta yoshli, tajribali kishilardek fikr yuritadigan.", "note": null},
  {"num": 496, "time": "00:34:45,519 --> 00:34:49,259", "arabic": "إِنَّهُ نَادِرَةٌ مِنْ نَوَادِرِ هَذَا الزَّمَانِ", "segs": null, "full_uz": "U bu zamonning noyob hodisalaridan biri.", "note": null},
  {"num": 497, "time": "00:34:49,259 --> 00:34:51,619", "arabic": "وَكُلِّ زَمَانٍ يَا مَوْلَايَ", "segs": null, "full_uz": "Va har qanday zamonning ham, xo'jayinim.", "note": null},
  {"num": 498, "time": "00:34:51,619 --> 00:34:52,900", "arabic": "صَدَقْتَ", "segs": null, "full_uz": "Haq gap aytding.", "note": null},
  {"num": 499, "time": "00:34:52,900 --> 00:34:55,360", "arabic": "صَدَقْتَ يَا ابْنَ سَهْلٍ", "segs": null, "full_uz": "Haq gap aytding, Ibn Sahl.", "note": null},
  {"num": 500, "time": "00:34:55,360 --> 00:34:59,820", "arabic": "فَإِنَّ فِي هَذَا الْفَتَى حَزْمَ جَدِّي الْمَنْصُورِ", "segs": null, "full_uz": "Bu yigitda bobom Mansurning qat'iyati bor.", "note": null},
  {"num": 501, "time": "00:34:59,820 --> 00:35:02,639", "arabic": "وَتُقَى أَبِي الْمَهْدِيِّ", "segs": null, "full_uz": "Otam Mahdiyning taqvosi.", "note": null},
  {"num": 502, "time": "00:35:02,639 --> 00:35:05,500", "arabic": "وَعِزَّةَ نَفْسِ أَخِي الْهَادِي", "segs": null, "full_uz": "Va akam Hodiyning izzat-nafsi.", "note": null},
  {"num": 503, "time": "00:35:05,500 --> 00:35:10,400", "arabic": "وَوَاللَّهِ لَوْ شِئْتُ أَنْ أَقُولَ الرَّابِعَةَ مِنِّي لَقُلْتُ", "segs": null, "full_uz": "Alloh haqqi, agar to'rtinchisini o'zimdan aytmoqchi bo'lsam, aytardim.", "note": null},
  {"num": 504, "time": "00:35:10,400 --> 00:35:16,380", "arabic": "فَكَيْفَ بِكَ بِأَبِي مُوسَى الْأَمِينِ وَلِيِّ عَهْدِكُمْ يَا أَمِيرَ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Xo'sh, valiahdingiz Abu Muso al-Amin haqida nima deysiz, ey mo'minlar amiri?", "note": null},
  {"num": 505, "time": "00:35:16,380 --> 00:35:19,240", "arabic": "إِنَّ الْأَمِينَ يَقِلُّ شَأْنًا عَنْ أَخِيهِ", "segs": null, "full_uz": "Amin martabada akasidan pastroq.", "note": null},
  {"num": 506, "time": "00:35:19,239 --> 00:35:23,099", "arabic": "وَمَنْ مِثْلُ أَبِي مُوسَى الْأَمِينِ فِي بَذْلِهِ وَجُودِهِ؟", "segs": null, "full_uz": "Abu Muso al-Aminga uning saxovati va saxiyligida kim tenglasha oladi?", "note": null},
  {"num": 507, "time": "00:35:23,099 --> 00:35:26,439", "arabic": "إِنَّهُ يَتَأَسَّى خُطَى أَجْدَادِهِ الْهَاشِمِيِّينَ", "segs": null, "full_uz": "U hoshimiy bobolarining izidan boradi.", "note": null},
  {"num": 508, "time": "00:35:26,439 --> 00:35:27,279", "arabic": "أَحْسَنْتَ", "segs": null, "full_uz": "Barakalla.", "note": null},
  {"num": 509, "time": "00:35:27,279 --> 00:35:30,379", "arabic": "أَحْسَنْتَ الْقَوْلَ يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Gapni chiroyli aytding, Ibn Rabi.", "note": null},
  {"num": 510, "time": "00:35:30,379 --> 00:35:33,699", "arabic": "قُلْ لِي يَا ابْنَ سَهْلٍ", "segs": null, "full_uz": "Ayt-chi, Ibn Sahl.", "note": null},
  {"num": 511, "time": "00:35:33,699 --> 00:35:37,519", "arabic": "أَيْنَ جَعْفَرٌ لَمْ أَرَهُ فِي مَجْلِسِي مُنْذُ يَوْمَيْنِ", "segs": null, "full_uz": "Ja'far qayerda, uni majlisimda ikki kundan beri ko'rmayapman.", "note": null},
  {"num": 512, "time": "00:35:37,519 --> 00:35:42,799", "arabic": "إِنَّ أَبَا الْفَضْلِ لَا يَشْغَلُهُ عَنْ أَمِيرِ الْمُؤْمِنِينَ شَاغِلٌ يَا مَوْلَايَ", "segs": null, "full_uz": "Abul-Fazlni mo'minlar amiridan hech narsa chalg'itmaydi, xo'jayinim.", "note": null},
  {"num": 513, "time": "00:35:42,799 --> 00:35:46,959", "arabic": "وَلَكِنْ أَحْسَبُ أَنَّ السَّهَرَ عَلَى شُؤُونِ دَوْلَةِ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Lekin menimcha, mo'minlar amiri davlati ishlarida tunlarni bedor o'tkazishi.", "note": null},
  {"num": 514, "time": "00:35:46,960 --> 00:35:50,740", "arabic": "عَاقَهُ عَنْ حُضُورِ مَجْلِسِكَ الْيَوْمَ يَا مَوْلَايَ الرَّشِيدُ", "segs": null, "full_uz": "Bugun majlisingizga kelishiga to'sqinlik qilgandir, xo'jayinim Rashid.", "note": null},
  {"num": 515, "time": "00:35:50,740 --> 00:35:55,500", "arabic": "أَوْ أَنَّهُ مَشْغُولٌ عَنْكَ يَا مَوْلَايَ بِقَصْرِهِ الْجَدِيدِ", "segs": null, "full_uz": "Yoki, xo'jayinim, sizdan yangi saroyi bilan mashg'ul bo'lib chalg'iganmi.", "note": null},
  {"num": 516, "time": "00:35:55,500 --> 00:36:00,519", "arabic": "اَلَّذِي أَنْفَقَ عَلَيْهِ عِشْرِينَ أَلْفَ أَلْفِ دِرْهَمٍ كَمَا يُقَالُ", "segs": null, "full_uz": "Aytishlaricha, unga yigirma million dirham sarflagan ekan.", "note": null},
  {"num": 517, "time": "00:36:00,519 --> 00:36:05,300", "arabic": "أَرَى أَنَّ هَذَا الرَّقْمَ مُبَالَغٌ فِيهِ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Menimcha, bu raqam mubolag'a qilingan, Abul-Abbos.", "note": null},
  {"num": 518, "time": "00:36:05,300 --> 00:36:08,300", "arabic": "بَلْ إِنَّهُ أَكْثَرُ مِمَّا تَحْسِبُ يَا ابْنَ سَهْلٍ", "segs": null, "full_uz": "Yo'q, bu siz o'ylaganingizdan ham ko'proq, Ibn Sahl.", "note": null},
  {"num": 519, "time": "00:36:08,300 --> 00:36:12,480", "arabic": "إِنَّ جَعْفَرًا لَدَيْهِ مِنَ الدُّورِ وَالْقُصُورِ الْكَثِيرُ", "segs": null, "full_uz": "Ja'farning o'zida ko'plab uy va saroylar bor.", "note": null},
  {"num": 520, "time": "00:36:12,480 --> 00:36:15,300", "arabic": "فَمَا حَاجَتُهُ لِبِنَاءِ قَصْرٍ جَدِيدٍ؟", "segs": null, "full_uz": "Unga yangi saroy qurishning nima keragi bor?", "note": null},
  {"num": 521, "time": "00:36:15,300 --> 00:36:18,060", "arabic": "دَعْكَ مِنْ هَذَا الْحَدِيثِ يَا عِيسَى", "segs": null, "full_uz": "Bu gapni qo'yib tur, Iso.", "note": null},
  {"num": 522, "time": "00:36:18,060 --> 00:36:20,560", "arabic": "قُلْ لِي يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Ayt-chi, Ibn Rabi.", "note": null},
  {"num": 523, "time": "00:36:20,560 --> 00:36:22,880", "arabic": "مَا أَخْبَارُ ضَيْفِكَ؟", "segs": null, "full_uz": "Mehmoning haqida nima xabar bor?", "note": null},
  {"num": 524, "time": "00:36:22,880 --> 00:36:25,780", "arabic": "مَوْلَايَ الرَّشِيدُ يَقْصِدُ الشَّافِعِيَّ؟", "segs": null, "full_uz": "Xo'jayinim Rashid Shofi'iyni nazarda tutyaptimi?", "note": null},
  {"num": 525, "time": "00:36:25,780 --> 00:36:29,539", "arabic": "لَقَدِ اسْتَأْثَرَ بِهِ قَاضِي قُضَاتِكَ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Uni bosh qoziyingiz o'ziga ajratib olgan, ey mo'minlar amiri.", "note": null},
  {"num": 526, "time": "00:36:29,539 --> 00:36:33,560", "arabic": "إِذَنْ فَقَدْ أَسْدَيْنَا مَعْرُوفًا لِابْنِ الْحَسَنِ", "segs": null, "full_uz": "Demak, Ibn Hasanga yaxshilik qilgan ekanmiz.", "note": null},
  {"num": 527, "time": "00:36:33,560 --> 00:36:36,900", "arabic": "إِذَا أَبْقَيْنَا عَلَى مُحَمَّدِ بْنِ إِدْرِيسَ الشَّافِعِيِّ فِي بَغْدَادَ", "segs": null, "full_uz": "Muhammad ibn Idris ash-Shofi'iyni Bag'dodda qoldirgan bo'lsak.", "note": null},
  {"num": 528, "time": "00:36:36,900 --> 00:36:37,840", "arabic": "أَلَيْسَ كَذَلِكَ؟", "segs": null, "full_uz": "Shunday emasmi?", "note": null},
  {"num": 548, "time": "00:37:38,300 --> 00:37:39,300", "arabic": "أُمَّ حَسَنٍ", "segs": null, "full_uz": "Umm Hasan!", "note": null},
  {"num": 549, "time": "00:37:39,300 --> 00:37:40,300", "arabic": "تَعَالَيْ", "segs": null, "full_uz": "Kel.", "note": null},
  {"num": 551, "time": "00:37:44,300 --> 00:37:45,300", "arabic": "فَوْزُ", "segs": null, "full_uz": "Fawz!", "note": null},
  {"num": 552, "time": "00:37:47,300 --> 00:37:51,300", "arabic": "خُذِي طَعَامَكِ أُرِيدُكِ أَنْ تَأْكُلِيهِ كُلَّهُ", "segs": null, "full_uz": "Ovqatingni ol, hammasini yeishingni istayman.", "note": null},
  {"num": 553, "time": "00:37:52,300 --> 00:37:55,300", "arabic": "أُرِيدُكِ أَنْ تَسْتَعِيدِي رَوْنَقَكِ وَعَافِيَتَكِ", "segs": null, "full_uz": "Yorqinligingni va sog'lig'ingni qaytarib olishingni istayman.", "note": null},
  {"num": 554, "time": "00:37:58,300 --> 00:38:02,300", "arabic": "لَا أُرِيدُ لِلرَّجُلِ أَنْ يَأْتِيَ وَيَرَاكِ وَأَنْتِ بِهَذَا الشُّحُوبِ", "segs": null, "full_uz": "U kishi kelib, seni shu ranging oqarib ketgan holda ko'rishini xohlamayman.", "note": null},
  {"num": 555, "time": "00:38:03,300 --> 00:38:04,300", "arabic": "كُلِي كُلِي", "segs": null, "full_uz": "Ye, ye.", "note": null},
  {"num": 556, "time": "00:38:08,300 --> 00:38:14,140", "arabic": "مَا بِكِ؟ لِمَ لَا تَرُدِّينَ؟ مُنْذُ غَادَرَنَا الرَّجُلُ وَأَنْتِ عَلَى صَمْتِكِ هَذَا", "segs": null, "full_uz": "Senga nima bo'ldi? Nega javob bermayapsan? U kishi ketganidan beri shu jimjitligingda qolyapsan.", "note": null},
  {"num": 557, "time": "00:38:14,140 --> 00:38:19,519", "arabic": "أَلَنْ تُخْبِرِينِي بِمَا دَارَ بَيْنَكُمَا مِنْ حَدِيثٍ؟", "segs": null, "full_uz": "Ikkovingiz orasida qanday suhbat bo'lganini menga aytmaysanmi?", "note": null},
  {"num": 558, "time": "00:38:19,519 --> 00:38:26,200", "arabic": "يَبْدُو أَنَّكِ قَدْ خَرِسْتِ وَلَا فَائِدَةَ مِنَ الْحَدِيثِ مَعَكِ", "segs": null, "full_uz": "Ko'rinishidan, tilingni yutib qo'ygansan, sen bilan gaplashishning foydasi yo'q.", "note": null},
  {"num": 559, "time": "00:38:26,200 --> 00:38:30,300", "arabic": "مَتَى سَيَأْتِي الْيَوْمُ الَّذِي أَرْتَاحُ فِيهِ مِنْكِ؟", "segs": null, "full_uz": "Sendan qutuladigan kun qachon keladi?", "note": null},
  {"num": 560, "time": "00:38:38,300 --> 00:38:49,080", "arabic": "هَلْ سَيَعُودُ؟", "segs": null, "full_uz": "U qaytadimi?", "note": null},
  {"num": 561, "time": "00:38:49,080 --> 00:38:50,120", "arabic": "لَا أَظُنُّ", "segs": null, "full_uz": "O'ylamayman.", "note": null},
  {"num": 562, "time": "00:38:50,120 --> 00:38:56,620", "arabic": "لِمَاذَا سَيَعُودُ؟", "segs": null, "full_uz": "Nega qaytar ekan?", "note": null},
  {"num": 563, "time": "00:38:56,620 --> 00:38:58,620", "arabic": "لَا عَقْلَ يَقْبَلُ مَا اشْتَرَطْتِ عَلَيْهِ", "segs": null, "full_uz": "Sen unga qo'ygan shartni hech qanday aql qabul qilmaydi.", "note": null},
  {"num": 564, "time": "00:38:58,620 --> 00:39:01,720", "arabic": "وَلَكِنْ مَعَ ذَلِكَ لَنْ أَفْقِدَ الْأَمَلَ", "segs": null, "full_uz": "Lekin shunga qaramay, umidimni yo'qotmayman.", "note": null},
  {"num": 565, "time": "00:39:01,720 --> 00:39:04,420", "arabic": "رُبَّمَا يَعُودُ", "segs": null, "full_uz": "Balki qaytar.", "note": null},
  {"num": 566, "time": "00:39:04,420 --> 00:39:06,300", "arabic": "يَا رَبِّ", "segs": null, "full_uz": "Ey Robbim.", "note": null},
  {"num": 567, "time": "00:39:06,300 --> 00:39:09,260", "arabic": "فَرِّجْ عَنِّي مَا أَنَا فِيهِ", "segs": null, "full_uz": "Men ichida bo'lgan holatimni yengillashtir.", "note": null},
  {"num": 568, "time": "00:39:09,260 --> 00:39:10,820", "arabic": "يَا رَبِّ", "segs": null, "full_uz": "Ey Robbim.", "note": null},
  {"num": 569, "time": "00:39:10,820 --> 00:39:14,360", "arabic": "سَأَفْتَحُ بَيْتًا جَدِيدًا", "segs": null, "full_uz": "Yangi bir uy ochaman.", "note": null},
  {"num": 570, "time": "00:39:14,360 --> 00:39:15,660", "arabic": "هَذِهِ الْأَغْرَاضُ تَلْزَمُنَا", "segs": null, "full_uz": "Bu buyumlar bizga kerak.", "note": null},
  {"num": 571, "time": "00:39:15,660 --> 00:39:17,340", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 572, "time": "00:39:17,340 --> 00:39:28,820", "arabic": "أَخَفْتَنِي يَا رَجُلُ", "segs": null, "full_uz": "Meni qo'rqitib yubording, birodar.", "note": null},
  {"num": 573, "time": "00:39:28,820 --> 00:39:30,740", "arabic": "مَا لَكَ مُسْتَعْجِلٌ هَكَذَا؟", "segs": null, "full_uz": "Senga nima bo'ldi, bunchalik shoshilyapsan?", "note": null},
  {"num": 574, "time": "00:39:30,740 --> 00:39:31,720", "arabic": "لَدَيَّ عَمَلٌ", "segs": null, "full_uz": "Ishim bor.", "note": null},
  {"num": 575, "time": "00:39:31,720 --> 00:39:33,240", "arabic": "عَمَلٌ", "segs": null, "full_uz": "Ish.", "note": null},
  {"num": 576, "time": "00:39:33,239 --> 00:39:40,779", "arabic": "وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ", "segs": null, "full_uz": "Va ayt: «Amal qilinglar, Alloh, Uning rasuli va mo'minlar amalingizni ko'radi».", "note": "Qur'ondagi (Tavba, 105-oyat) iqtibos."},
  {"num": 577, "time": "00:39:40,779 --> 00:39:43,579", "arabic": "وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ", "segs": null, "full_uz": "Va g'ayb hamda shohidlikni Biluvchi tomon qaytarilasizlar.", "note": null},
  {"num": 578, "time": "00:39:43,579 --> 00:39:46,839", "arabic": "فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ", "segs": null, "full_uz": "U sizlarga qilgan amallaringiz haqida xabar beradi.", "note": null},
  {"num": 579, "time": "00:39:46,839 --> 00:39:48,239", "arabic": "مَاذَا بَعْدُ؟", "segs": null, "full_uz": "Yana nima bor?", "note": null},
  {"num": 580, "time": "00:39:50,019 --> 00:39:53,739", "arabic": "يَعْلَمُ خَائِنَةَ الْأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ", "segs": null, "full_uz": "U ko'zlarning xiyonatini va ko'ngillar yashirgan narsani biladi.", "note": "Qur'ondagi (G'ofir, 19-oyat) ma'nosiga ishora."},
  {"num": 581, "time": "00:39:53,739 --> 00:39:55,239", "arabic": "مَاذَا تَقْصِدُ؟", "segs": null, "full_uz": "Nimani nazarda tutyapsan?", "note": null},
  {"num": 582, "time": "00:39:55,959 --> 00:39:59,639", "arabic": "لَا تَنْقُصُكَ الْفِطْنَةُ يَا ابْنَ أُمِّ فَرَجٍ", "segs": null, "full_uz": "Zukkolik senga yetishmaydigan narsa emas, ey Umm Faraj o'g'li.", "note": null},
  {"num": 583, "time": "00:40:03,239 --> 00:40:12,359", "arabic": "بَلْ يَنْقُصُنِي الْكَثِيرُ", "segs": null, "full_uz": "Yo'q, menga ko'p narsa yetishmaydi.", "note": null},
  {"num": 584, "time": "00:40:12,359 --> 00:40:21,859", "arabic": "أَرْسَلْتَ فِي طَلَبِي", "segs": null, "full_uz": "Meni chaqirtirgan ekansiz.", "note": null},
  {"num": 585, "time": "00:40:21,859 --> 00:40:26,619", "arabic": "أَجَلْ وَأَنْتَظِرُ مِنْكَ أَخْبَارًا", "segs": null, "full_uz": "Ha, sendan xabarlar kutyapman.", "note": null},
  {"num": 586, "time": "00:40:26,619 --> 00:40:28,099", "arabic": "لَقَدْ نَقَلْتُ إِلَيْكَ كُلَّ مَا سَمِعْتُ", "segs": null, "full_uz": "Eshitganlarimning barchasini sizga yetkazdim.", "note": null},
  {"num": 587, "time": "00:40:28,099 --> 00:40:29,000", "arabic": "اُدْخُلْ", "segs": null, "full_uz": "Kir.", "note": null},
  {"num": 588, "time": "00:40:29,000 --> 00:40:39,179", "arabic": "اِسْمَعْ كُلُّ مَا نَقَلْتَهُ لِي لَا أَهَمِّيَّةَ لَهُ", "segs": null, "full_uz": "Eshit, menga yetkazganlaringning barchasi ahamiyatsiz.", "note": null},
  {"num": 589, "time": "00:40:39,179 --> 00:40:42,139", "arabic": "مَا كَلَّفْتُكَ بِهِ لَيْسَ بِالْأَمْرِ السَّهْلِ", "segs": null, "full_uz": "Senga topshirgan ishim oson emas.", "note": null},
  {"num": 590, "time": "00:40:42,139 --> 00:40:46,599", "arabic": "كُنْتَ لَا تَسْتَطِيعُ تَصَيُّدَ الْأَخْبَارِ الْمُهِمَّةِ", "segs": null, "full_uz": "Muhim xabarlarni ovlashga qodir emas ekansan.", "note": null},
  {"num": 591, "time": "00:40:46,599 --> 00:40:49,000", "arabic": "فَدَعْنِي أَبْحَثْ عَنْ بَدِيلٍ لَكَ", "segs": null, "full_uz": "Senga o'rin bosar qidirishimga imkon ber.", "note": null},
  {"num": 592, "time": "00:40:49,000 --> 00:40:54,320", "arabic": "فَهُنَاكَ الْكَثِيرُ يَنْتَظِرُ أَنْ يَخْدُمَ أَمْنَ هَذِهِ الْبِلَادِ", "segs": null, "full_uz": "Bu yurt xavfsizligiga xizmat qilishni kutayotgan ko'plar bor.", "note": null},
  {"num": 593, "time": "00:40:54,320 --> 00:40:57,599", "arabic": "وَمِنْ أَيْنَ آتِيكَ بِالْأَخْبَارِ الْمُهِمَّةِ؟", "segs": null, "full_uz": "Muhim xabarlarni sizga qayerdan olib kelay?", "note": null},
  {"num": 594, "time": "00:40:57,599 --> 00:41:01,599", "arabic": "أَتُرِيدُنِي أَنْ أَخْتَلِقَهَا وَأَظْلِمَ النَّاسَ؟", "segs": null, "full_uz": "Meni ularni to'qib chiqarib, odamlarga zulm qilishimni xohlaysizmi?", "note": null},
  {"num": 595, "time": "00:41:01,599 --> 00:41:04,599", "arabic": "اَلْأَخْبَارُ لَا تَسْعَى بَلْ يُسْعَى إِلَيْهَا", "segs": null, "full_uz": "Xabarlar o'zi kelmaydi, ularning ortidan borish kerak.", "note": null},
  {"num": 596, "time": "00:41:04,599 --> 00:41:10,599", "arabic": "فَتِّشْ عَنْهَا وَمَنْ لَا يُرِيدُ الْحَدِيثَ اسْتَدْرِجْهُ لِيَبُوحَ بِمَا يُخْفِي", "segs": [{"ar": "فَتِّشْ عَنْهَا", "uz": "ularni qidir"}, {"ar": "وَمَنْ لَا يُرِيدُ الْحَدِيثَ اسْتَدْرِجْهُ لِيَبُوحَ بِمَا يُخْفِي", "uz": "gaplashishni istamaydigan kishini esa hiyla bilan gapga solib, yashirganini oshkor qildir"}], "full_uz": "Ularni qidir, gaplashishni istamaydigan kishini esa yashirgan narsasini oshkor qilishga undab, hiyla bilan gapga sol.", "note": null},
  {"num": 597, "time": "00:41:11,599 --> 00:41:15,599", "arabic": "أَنْتَ شَابٌّ ذَكِيٌّ وَلَا تَنْقُصُكَ الْفِطْنَةُ", "segs": null, "full_uz": "Sen aqlli yigitsan, zukkolik senda yetarli.", "note": null},
  {"num": 598, "time": "00:41:16,599 --> 00:41:18,599", "arabic": "سَأُحَاوِلُ", "segs": null, "full_uz": "Harakat qilaman.", "note": null},
  {"num": 599, "time": "00:41:19,599 --> 00:41:23,599", "arabic": "عَمَّا قَرِيبٍ سَتَسْمَعُ مِنِّي مَا يَسُرُّكَ", "segs": null, "full_uz": "Tez orada mendan sizni xursand qiladigan narsani eshitasiz.", "note": null},
  {"num": 600, "time": "00:41:23,599 --> 00:41:25,519", "arabic": "هَيَّا عُودِي لِعَمَلِكِ", "segs": null, "full_uz": "Yur, ishingga qayt.", "note": null},
  {"num": 601, "time": "00:41:25,519 --> 00:41:28,360", "arabic": "وَأَنَا أَنْتَظِرُ مِنْكِ أَخْبَارًا", "segs": null, "full_uz": "Men esa sendan xabarlar kutaman.", "note": null},
  {"num": 602, "time": "00:41:28,360 --> 00:41:29,719", "arabic": "هَيَّا", "segs": null, "full_uz": "Yur.", "note": null}
];
